/* [C] Buttons - CMet - SITEWIDE applicable to components using .btn-cmet and intext buttons using .btn-cmet-intext - DO NOT EDIT ON  INSTANCE SPECIFIC BASIS */
/* Buttons - CMet - Default behaviour and presentational rules to be used in conjunction with Buttons - CMet Colour Classes */
.btn-cmet {
    --cmet-btn-padding-x: 0.75rem;
    --cmet-btn-padding-y: 0.375rem;
    --cmet-btn-font-family: var(--cmet-body-font-family);
    --cmet-btn-font-size: clamp(1rem, calc(1.275*var(--cmet-body-font-size)), 1.375rem);
    --cmet-btn-line-height: 1.6;
    --cmet-btn-color: var(--cmet-btn-color);
    --cmet-btn-bg: transparent;
    --cmet-btn-border-width: calc(0.56*var(--cmet-border-width));
    --cmet-btn-border-color: var(--cmet-btn-border-color);
    --cmet-btn-border-radius: var(--cmet-border-radius);
    --cmet-btn-hover-border-color: transparent;
    --cmet-btn-box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.35), 0 1px 2px rgba(0, 0, 0, 0.55);
    --cmet-btn-disabled-opacity: 0.65;
    --cmet-btn-focus-box-shadow: 0 0 0 0.25rem rgba(var(--bs-btn-focus-shadow-rgb), .5);
    display: inline-block;
    padding: var(--cmet-btn-padding-y) var(--cmet-btn-padding-x);
    font-family: var(--cmet-btn-font-family);
    font-size: var(--cmet-btn-font-size);
    font-weight: var(--cmet-btn-font-weight);
    line-height: var(--cmet-btn-line-height);
    color: var(--cmet-btn-color);
    text-align: center;
    text-decoration: none;
    vertical-align: middle;
    cursor: pointer;
    -webkit-user-select: none;
    -moz-user-select: none;
    user-select: none;
    border: var(--cmet-btn-border-width) solid var(--cmet-btn-border-color);
    border-radius: var(--cmet-border-radius);
    background-color: var(--cmet-btn-bg);
    transition: color 0.15s ease-in-out, background-color 0.4s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.4s ease-in-out;
}

.btn-cmet:hover {
    color: var(--cmet-btn-hover-color);
    background-color: var(--cmet-btn-hover-bg);
    border-color: var(--cmet-btn-hover-border-color);
    text-decoration: none;
}

.btn-cmet.focus,
.btn-cmet:focus {
    color: var(--cmet-btn-color);
    border-radius: var(--cmet-border-radius);
    text-decoration: none;
}

.btn-cmet-intext {
    --cmet-btn-intext-padding-y: calc(var(--cmet-btn-padding-y) / 100 * 10);
    --cmet-btn-intext-padding-x: calc(var(--cmet-btn-padding-x) / 100 * 80);
    padding: 0 var(--cmet-btn-intext-padding-x);
    margin: 0 0.1em;
    vertical-align: baseline;
}

