/* CMET SPACING >>>>>>>>>>>>>>> */

:root {
    --cm-space-025: clamp(0.25rem, 0.235rem + 0.0752vi, 0.3125rem);
    --cm-space-050: clamp(0.5rem, 0.4699rem + 0.1504vi, 0.625rem);
    --cm-space-075: clamp(0.75rem, 0.7049rem + 0.2256vi, 0.9375rem);
    --cm-space-100: clamp(1rem, 0.9398rem + 0.3008vi, 1.25rem);
    --cm-space-125: clamp(1.25rem, 1.1748rem + 0.3759vi, 1.5625rem);
    --cm-space-150: clamp(1.5rem, 1.4098rem + 0.4511vi, 1.875rem);
    --cm-space-175: clamp(1.75rem, 1.6447rem + 0.5263vi, 2.1875rem);
    --cm-space-200: clamp(2rem, 1.8797rem + 0.6015vi, 2.5rem);
    --cm-space-300: clamp(3rem, 2.8195rem + 0.9023vi, 3.75rem);
    --cm-space-400: clamp(4rem, 3.7594rem + 1.203vi, 5rem);
    --cm-space-500: clamp(5rem, 4.6992rem + 1.5038vi, 6.25rem);
    --cm-space-600: clamp(6rem, 5.6391rem + 1.8045vi, 7.5rem);

    /* One-up pairs */
    --cm-space-025-050: clamp(0.25rem, 0.1598rem + 0.4511vi, 0.625rem);
    --cm-space-050-075: clamp(0.5rem, 0.3947rem + 0.5263vi, 0.9375rem);
    --cm-space-075-100: clamp(0.75rem, 0.6297rem + 0.6015vi, 1.25rem);
    --cm-space-100-125: clamp(1rem, 0.8647rem + 0.6767vi, 1.5625rem);
    --cm-space-125-150: clamp(1.25rem, 1.0996rem + 0.7519vi, 1.875rem);
    --cm-space-150-175: clamp(1.5rem, 1.3346rem + 0.8271vi, 2.1875rem);
    --cm-space-175-200: clamp(1.75rem, 1.5695rem + 0.9023vi, 2.5rem);
    --cm-space-200-300: clamp(2rem, 1.5789rem + 2.1053vi, 3.75rem);
    --cm-space-300-400: clamp(3rem, 2.5188rem + 2.406vi, 5rem);
    --cm-space-400-500: clamp(4rem, 3.4586rem + 2.7068vi, 6.25rem);
    --cm-space-500-600: clamp(5rem, 4.3985rem + 3.0075vi, 7.5rem);

    /* Custom pairs */
    --cm-space-100-150: clamp(1rem, 0.6391rem + 1.8045vi, 2.5rem);
    --cm-space-400-600: clamp(4rem, 3.1579rem + 4.2105vi, 7.5rem);

    /* cmet gutters */
    --cm-gutter-x: calc(var(--cm-space-100)*1.5);
    --cm-gutter-y: calc(var(--cm-space-100)*0);
}

