/* CMET STYLE: BOX MODEL */
:root {
    /* box model spacing root variables*/
    --cm-border-radius: 0.32rem;
    /* If 1rem = 16px then 0.355rem = 4.5px and 0.32rem = 5px and 0.25rem = 4px */
    --cm-border-width: 0.1rem;
    --cm-border-width-px: calc(var(--cm-font-size) / 10);
    --cm-border-style: solid;
    --cm-outline-width: 0.1rem;
    --cm-outline-inner-width: 0.1rem;
}


