/* cm accordions */

/* cm-accordion */
.accordion {
    --cm-accord-transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out, border-radius 0.15s ease;
    --cm-accord-border-radius: var(--cm-border-radius);
