    border: 0;
    border-radius: var(--cm-border-radius);
    overflow-anchor: none;
    transition: var(--cm-accord-transition);
}

@media (prefers-reduced-motion: reduce) {
    .accordion-button {
        transition: none;
    }
}

.accordion-button::after {
    flex-shrink: 0;
    margin-left: auto;
    content: "";
    background-repeat: no-repeat;
    transition: var(--cm-accord-btn-icon-transition);
}

@media (prefers-reduced-motion: reduce) {
