/* cmet-sidewide-nav */
/* Styles for self-contained independent sitwide menu - These styles are custom and independent of lg/bs collapsible menu styles */

/* cmet-sidewide-nav styling - can be removed from OLD - check li though */

/*sitewide collapsible navbar */
/* Custom Collapsible Navbar Styles */

/* cmet-sidewide-nav styling - can be removed from OLD */
#cmet-sitewide-nav {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    padding: 10px 0px;
    background-color: rgb(0, 0, 0);
    cursor: default;
    margin-left: auto;
    margin-right: auto;
}

.cmet-sitewide-navbar-wrapper {
    display: flex;
    flex-wrap: wrap;
    /* Allows collapse content to wrap */
    align-items: center;
    justify-content: center;
    /* Ensures the whole navbar content is centered on mobile */
    padding: 0.5rem 1rem;
    background-color: transparent;
    width: 100%;
}

.cmet-sitewide-navbar-container {
    display: flex;
    flex-wrap: wrap;
    /* Allows brand and toggler to wrap if needed */
    align-items: center;
    /* Centers items vertically in a row */
    justify-content: center;
    /* Default: Center brand and toggler together */
    width: 100%;
}

.cmet-sitewide-navbar-brand {
    padding-top: 0.3125rem;
    padding-bottom: 0.3125rem;
    margin-right: 0;
    /* Reset margin */
    font-size: 1.25rem;
    text-decoration: none;
    white-space: nowrap;
    color: initial;
    /* Removed specific text color */
    margin-bottom: 0;
    /* Default */
}

.cmet-sitewide-navbar-brand:hover,
.cmet-sitewide-navbar-brand:focus {
    color: initial;
}

/* Toggler Button (Hamburger Icon) */
.cmet-sitewide-navbar-toggler {
    padding: 0.25rem 0.75rem;
    font-size: 1.25rem;
    line-height: 1;
    background-color: transparent;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    display: block;
    /* Always display toggler by default (for mobile first) */
    margin: 0;
    /* Reset default margins */
}

.cmet-sitewide-toggler-icon {
    display: inline-block;
    width: 1.5em;
    height: 1.5em;
    vertical-align: middle;
    background-repeat: no-repeat;
    background-position: center;
    background-size: 100%;
    background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='rgb%28255,255,255%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
}

/* Collapsible Menu Content */
.cmet-sitewide-navbar-collapse {
    flex-basis: 100%;
    flex-grow: 1;
    align-items: center;
    /* Default initial state: HIDDEN */
    height: 0;
    overflow: hidden;
    display: none;
    /* <--- ADDED: Explicitly hide it by default */
    transition: height 0.35s ease;
    justify-content: center;
}

.cmet-sitewide-navbar-collapse.cmet-sitewide-show {
    height: auto;
    overflow: visible;
    display: flex;
    /* <--- MODIFIED: Ensure it becomes flex when the 'show' class is added */
}

/* Navigation List */
.cmet-sitewide-navbar-nav {
    display: flex;
    flex-direction: column;
    /* Stacked by default on small screens */
    padding-left: 0;
    margin-bottom: 0;
    list-style: none;
    width: 100%;
    /* Take full width within its container */
    margin-top: 0.5rem;
    /* Space below brand/toggler on small screens */
    align-items: center;
    /* Center stacked items horizontally */
}

.cmet-sitewide-nav-item {
    margin-bottom: 0;
}

.cmet-sitewide-nav-link {
    display: block;
    padding: 0.5rem 0;
    /* Vertical padding, no horizontal padding initially */
    color: inherit;
    text-decoration: none;
    transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out;
}

.cmet-sitewide-nav-link:hover,
.cmet-sitewide-nav-link:focus {
    color: inherit;
}

/* Media Query for Small Screens (up to lg breakpoint: 991.98px) */
@media (max-width: 991.98px) {
    .cmet-sitewide-navbar-container {
        flex-direction: column;
        justify-content: center;
        align-items: center;
        margin-bottom: 0.5rem;
    }

    .cmet-sitewide-navbar-brand {
        margin-bottom: 0.5rem;
        margin-right: 0;
    }

    .cmet-sitewide-navbar-toggler {
        margin-top: 0.5rem;
        margin-bottom: 0.5rem;
    }

    .cmet-sitewide-navbar-wrapper {
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
        padding-bottom: 0;
    }
}

/* Media Query for Large Screens (lg breakpoint: 992px) */
@media (min-width: 992px) {
    .cmet-sitewide-navbar-wrapper {
        flex-wrap: nowrap;
        justify-content: flex-start;
        padding-bottom: 0.5rem;
    }

    .cmet-sitewide-navbar-container {
        flex-direction: row;
        justify-content: space-between;
        margin-bottom: 0;
    }

    .cmet-sitewide-navbar-brand {
        margin-right: 1rem;
        margin-bottom: 0;
    }

    .cmet-sitewide-navbar-toggler {
        display: none;
        /* Hide toggler on large screens */
        margin: 0;
    }

    /* Force display flex on large screens, overriding the default 'display: none' */
    .cmet-sitewide-navbar-collapse {
        display: flex !important;
        /* <--- MODIFIED: Ensure it's always flex on large screens */
        height: auto !important;
        /* <--- ADDED: Force height auto */
        overflow: visible !important;
        /* <--- ADDED: Force overflow visible */
        flex-basis: auto;
        justify-content: center;
        width: 100%;
    }

    .cmet-sitewide-navbar-nav {
        flex-direction: row;
        margin-top: 0;
        width: auto;
        margin-left: auto;
        margin-right: auto;
        align-items: flex-start;
    }

    .cmet-sitewide-nav-link {
        padding: 0.5rem 1rem;
    }

}


