.img-fluid {
    max-width: 100%;
    height: auto;
}

.img-thumbnail {
    padding: 0.25rem;
    background-color: var(--cmet-body-bg-color-primary-rgb);
    border: var(--cmet-border-width) solid var(--cmet-border-color-primary-rgb);
    border-radius: var(--cmet-border-radius);
    max-width: 100%;
    height: auto;
}

.figure {
    display: inline-block;
}

.figure-img {
    margin-bottom: 0.5rem;
    line-height: 1;
}

.figure-caption {
    font-size: 0.875em;
    color: var(--cmet-body-text-color-secondary);
}

/* OLD SECOND ---- START: TYPOGRAPHY -*/
:root {
    --cmet-font-size: 16px;
    /*- this also sets site wide setting for 1 rem -*/
    --cmet-font-size-fluid: clamp(1rem, 1rem + 0.0625vw, 1.166rem);
    --cmet-body-font-size: var(--cmet-font-size-fluid);
    --cmet-body-font-weight: 400;
    --cmet-body-line-height: 1.75;

    --cmet-font-sans-serif: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --cmet-font-monospace: SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --cmet-body-font-family: var(--cmet-font-sans-serif);

    --cmet-p-fs: var(--cmet-body-font-size);
    --cmet-h1-fs: clamp(2rem, 1.375rem + 1.5vw, 3rem);
    --cmet-h2-fs: clamp(1.5rem, 1.325rem + 0.9vw, 2.116rem);
    --cmet-h3-fs: clamp(1.3rem, 1.3rem + 0.6vw, 1.75rem);
    --cmet-h4-fs: clamp(1.275rem, 1.275rem + 0.3vw, 1.66rem);
    --cmet-h5-fs: clamp(1.25rem, 1.25rem + 0.15vw, 1.5rem);
    --cmet-h6-fs: clamp(1rem, 1rem + 0.116vw, 1.166rem);

    /* START: link-styling root variables */
    --cmet-link-opacity: 1;
    --cmet-link-color: var(--cmet-blue);
    --cmet-link-color-rgb: rgba(var(--cmet-blue-rgb), var(--cmet-link-opacity, 1));
    --cmet-link-border-bottom: 0.05rem dotted var(--cmet-link-color-rgb);
    --cmet-link-text-decoration: none;

    --cmet-link-hover-color: var(--cmet-navy-blue);
    --cmet-link-hover-color-rgb: rgba(var(--cmet-navy-blue-rgb), var(--cmet-link-opacity, 1));
    --cmet-link-hover-border-bottom: 0.1rem solid var(--cmet-link-hover-color-rgb);
    --cmet-link-hover-text-decoration: none;
}

/* START: TYPOGRAPHY  classes ---*/

html {
    font-size: var(--cmet-font-size);
    border-radius: var(--cmet-border-radius);
}

body {
    margin: 0;
    padding: 0;

    font-family: var(--cmet-body-font-family);
    font-size: var(--cmet-body-font-size);
    font-weight: var(--cmet-body-font-weight);
    line-height: var(--cmet-body-line-height);
