/* ===== /public/css/cm-utility-variables.css ===== */
/* =====================================================
   CM DESIGN SYSTEM - VARIABLES
   ===================================================== */

/*
   This file contains all CM design system CSS custom properties (variables)
   organized by category:
   
   - Box model variables (borders, spacing)
   - Typography variables (fonts, sizes, line heights)
   - Color variables (core colors, accent colors, semantic colors)
   - Shadow variables
   - Other utility variables
   
   These variables provide the foundation for all other utility classes
   and should be loaded first in the CSS cascade.
*/

/* ===== CSS CUSTOM PROPERTIES (VARIABLES) ===== */

/* CMET STYLE: BOX MODEL */
:root {
    /* box model spacing root variables*/
    --cm-border-radius: 0.375rem;
    /* Equivalent to bootstrap rounded-3 ; If 1rem = 16px then 0.355rem = 4.5px and 0.32rem = 5px and 0.25rem = 4px */
    --cm-border-width: 0.1rem;
    --cm-border-width-px: calc(var(--cm-font-size) / 10);
    --cm-border-style: solid;
    --cm-outline-width: 0.1rem;
    --cm-outline-inner-width: 0.1rem;
}

/* CMET STYLE: TYPOGRAPHY */
:root {
    /* cmet typography variables */
    --cm-font-size: 16px;
    /*- this also sets site wide setting for 1 rem -*/
    /*  --cm-font-size-fluid: clamp(1rem, 1rem + 0.0625vw, 1.166rem); */
    --cm-font-sans-serif: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --cm-font-monospace: SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --cm-body-font-size: var(--cm-font-size-0);
    --cm-body-font-weight: 400;
    --cm-body-line-height: 1.75;
    --cm-body-font-family: var(--cm-font-sans-serif);

    --cm-p-font-size: var(--cm-font-size-0);
    --cm-h1-font-size: var(--cm-font-size-5);
    --cm-h2-font-size: var(--cm-font-size-4);
    --cm-h3-font-size: var(--cm-font-size-3);
    --cm-h4-font-size: var(--cm-font-size-2);
    --cm-h5-font-size: var(--cm-font-size-1);
    --cm-h6-font-size: var(--cm-font-size-0);

    --cm-font-size--2: clamp(0.7901rem, 0.7426rem + 0.2376vi, 0.9877rem);
    --cm-font-size--1: clamp(0.8889rem, 0.8354rem + 0.2673vi, 1.1111rem);
    --cm-font-size-0: clamp(1rem, 0.9398rem + 0.3008vi, 1.25rem);
    --cm-font-size-1: clamp(1.125rem, 1.0573rem + 0.3383vi, 1.4063rem);
    --cm-font-size-2: clamp(1.2656rem, 1.1895rem + 0.3806vi, 1.582rem);
    --cm-font-size-3: clamp(1.4238rem, 1.3382rem + 0.4282vi, 1.7798rem);
    --cm-font-size-4: clamp(1.6018rem, 1.5055rem + 0.4817vi, 2.0023rem);
    --cm-font-size-5: clamp(1.802rem, 1.6936rem + 0.542vi, 2.2525rem);

    /*
    --cm-p-font-size: var(--cm-body-font-size);
    --cm-h1-font-size: clamp(2rem, 1.375rem + 1.5vw, 3rem);
    --cm-h2-font-size: clamp(1.5rem, 1.325rem + 0.9vw, 2.116rem);
    --cm-h3-font-size: clamp(1.3rem, 1.3rem + 0.6vw, 1.75rem);
    --cm-h4-font-size: clamp(1.275rem, 1.275rem + 0.3vw, 1.66rem);
    --cm-h5-font-size: clamp(1.25rem, 1.25rem + 0.15vw, 1.5rem);
    --cm-h6-font-size: clamp(1rem, 1rem + 0.116vw, 1.166rem);
*/
}

/* CMET STYLE: LINKS */
:root {
    /* cmet link styling variables */
    --cm-link-opacity: 1;
    --cm-link-color: var(--cm-blue);
    --cm-link-color-rgb: rgba(var(--cm-blue-rgb), var(--cm-link-opacity, 1));
    --cm-link-border-bottom: 0.05rem dotted var(--cm-link-color-rgb);
    --cm-link-text-decoration: none;
    --cm-link-hover-color: var(--cm-dark-blue);
    --cm-link-hover-color-rgb: rgba(var(--cm-dark-blue-rgb), var(--cm-link-opacity, 1));
    --cm-link-hover-border-bottom: 0.1rem solid var(--cm-link-hover-color-rgb);
    --cm-link-hover-text-decoration: none;
}

/* CMET PRESENTATIONAL STYLE: BOX SHADOWS*/
:root {
    --cm-boxshadow-inset00: inset 0 0px 0px rgba(9, 9, 9, 0.15);
    --cm-boxshadow-inset01: inset 0 1px 1px rgba(9, 9, 9, 0.055);
