/* ===== /public/css/cm-utility-animations.css ===== */
/* =====================================================
   CM DESIGN SYSTEM - ANIMATION UTILITIES
   ===================================================== */

/*
   This file contains all animation-related utility classes:
   
   - Keyframe definitions for custom animations
   - Animation utility classes for emphasis effects
   - Entry/exit animation classes
   - Transition utilities
   
   These utilities can be applied to any element to add dynamic effects
   and should be loaded after the core CM utility files.
*/

/* ===== KEYFRAME DEFINITIONS ===== */

/* Emphasis Animations */
@keyframes pulse-grow {

    0%,
    100% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.25);
    }
}

@keyframes shake-horizontal {

    10%,
    90% {
        transform: translateX(-1px);
    }

    20%,
    80% {
        transform: translateX(2px);
    }

    30%,
    50%,
    70% {
        transform: translateX(-4px);
    }

    40%,
    60% {
        transform: translateX(4px);
    }
}

@keyframes spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

@keyframes tada {
    from {
        transform: scale3d(1, 1, 1);
    }

    10%,
    20% {
        transform: scale3d(.9, .9, .9) rotate3d(0, 0, 1, -3deg);
    }

    30%,
    50%,
    70%,
    90% {
        transform: scale3d(1.1, 1.1, 1.1) rotate3d(0, 0, 1, 3deg);
    }

    40%,
    60%,
    80% {
        transform: scale3d(1.1, 1.1, 1.1) rotate3d(0, 0, 1, -3deg);
    }

    to {
        transform: scale3d(1, 1, 1);
    }
}

@keyframes jiggle {

    0%,
    100% {
        transform: rotate(-1deg);
    }

    50% {
        transform: rotate(1deg);
    }
}

@keyframes bounce {

    0%,
    20%,
    50%,
    80%,
    100% {
        transform: translateY(0);
    }

    40% {
        transform: translateY(-30%);
    }

    60% {
        transform: translateY(-15%);
    }
}

@keyframes flash {

    0%,
    50%,
    100% {
        opacity: 1;
    }

    25%,
    75% {
        opacity: 0.2;
    }
}

@keyframes wobble {
    0% {
        transform: none;
    }

    15% {
        transform: translate3d(-25%, 0, 0) rotate3d(0, 0, 1, -5deg);
    }

    30% {
        transform: translate3d(20%, 0, 0) rotate3d(0, 0, 1, 3deg);
    }

    45% {
        transform: translate3d(-15%, 0, 0) rotate3d(0, 0, 1, -3deg);
    }

    60% {
        transform: translate3d(10%, 0, 0) rotate3d(0, 0, 1, 2deg);
    }

    75% {
        transform: translate3d(-5%, 0, 0) rotate3d(0, 0, 1, -1deg);
    }

    100% {
        transform: none;
    }
}

@keyframes heartbeat {
    0% {
        transform: scale(1);
    }

    14% {
        transform: scale(1.3);
    }

    28% {
        transform: scale(1);
    }

    42% {
        transform: scale(1.3);
    }

    70% {
        transform: scale(1);
    }
}

/* Entry/Exit Animations */
@keyframes fade-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

@keyframes fade-out {
    from {
        opacity: 1;
    }

    to {
        opacity: 0;
    }
}

@keyframes zoom-in {
    from {
        opacity: 0;
        transform: scale(0);
    }

    to {
        opacity: 1;
        transform: scale(1);
    }
}

@keyframes zoom-out {
    from {
        opacity: 1;
        transform: scale(1);
    }

    to {
        opacity: 0;
        transform: scale(0);
    }
}

@keyframes slide-in-left {
    from {
        transform: translateX(-100%);
        opacity: 0;
    }

    to {
        transform: translateX(0);
        opacity: 1;
    }
}

@keyframes slide-out-right {
    from {
        transform: translateX(0);
        opacity: 1;
    }

    to {
        transform: translateX(100%);
        opacity: 0;
    }
}

@keyframes slide-in-top {
    from {
        transform: translateY(-100%);
        opacity: 0;
    }

    to {
        transform: translateY(0);
        opacity: 1;
    }
}

@keyframes slide-out-top {
    from {
        transform: translateY(0);
        opacity: 1;
    }

    to {
        transform: translateY(-100%);
        opacity: 0;
    }
}

@keyframes slide-in-bottom {
    from {
        transform: translateY(100%);
        opacity: 0;
    }

    to {
        transform: translateY(0);
        opacity: 1;
    }
}

@keyframes slide-out-bottom {
    from {
        transform: translateY(0);
        opacity: 1;
    }

    to {
        transform: translateY(100%);
        opacity: 0;
    }
}

@keyframes rotate-in {
    from {
        opacity: 0;
        transform: rotate(-360deg) scale(0);
    }

    to {
        opacity: 1;
        transform: rotate(0deg) scale(1);
    }
}

@keyframes rotate-out {
    from {
        opacity: 1;
        transform: rotate(0deg) scale(1);
    }

    to {
        opacity: 0;
        transform: rotate(360deg) scale(0);
    }
}

@keyframes flip-in-x {
    from {
        transform: perspective(400px) rotate3d(1, 0, 0, 90deg);
        opacity: 0;
    }

    to {
        transform: perspective(400px) rotate3d(1, 0, 0, 0deg);
        opacity: 1;
    }
}

@keyframes flip-out-x {
    from {
        transform: perspective(400px) rotate3d(1, 0, 0, 0deg);
        opacity: 1;
    }

    to {
        transform: perspective(400px) rotate3d(1, 0, 0, 90deg);
        opacity: 0;
    }
}

@keyframes roll-in {
    from {
        opacity: 0;
        transform: translateX(-100%) rotate(-120deg);
    }

    to {
        opacity: 1;
        transform: translateX(0) rotate(0deg);
    }
}

@keyframes roll-out {
    from {
        opacity: 1;
        transform: translateX(0) rotate(0deg);
    }

    to {
        opacity: 0;
        transform: translateX(100%) rotate(120deg);
    }
}

@keyframes light-speed-in {
    from {
        transform: translate3d(100%, 0, 0) skewX(-30deg);
        opacity: 0;
    }

    60% {
        transform: skewX(20deg);
        opacity: 1;
    }

    80% {
        transform: skewX(-5deg);
    }

    to {
        transform: translate3d(0, 0, 0);
    }
}

@keyframes light-speed-out {
    from {
        transform: translate3d(0, 0, 0);
        opacity: 1;
    }

    to {
        transform: translate3d(100%, 0, 0) skewX(30deg);
        opacity: 0;
    }
}

@keyframes hinge {
    0% {
        transform-origin: top left;
        animation-timing-function: ease-in-out;
    }

    20%,
    60% {
        transform: rotate3d(0, 0, 1, 80deg);
        transform-origin: top left;
        animation-timing-function: ease-in-out;
    }

    40%,
    80% {
        transform: rotate3d(0, 0, 1, 60deg);
        transform-origin: top left;
        animation-timing-function: ease-in-out;
        opacity: 1;
    }

    to {
        transform: translate3d(0, 700px, 0);
        opacity: 0;
    }
}

/* Additional Emphasis Animations */
@keyframes glow {

    0%,
    100% {
        box-shadow: 0 0 5px currentColor;
    }

    50% {
        box-shadow: 0 0 20px currentColor, 0 0 30px currentColor;
    }
}

@keyframes rubber-band {
    0% {
        transform: scale3d(1, 1, 1);
    }

    30% {
        transform: scale3d(1.25, 0.75, 1);
    }

    40% {
        transform: scale3d(0.75, 1.25, 1);
    }

    50% {
        transform: scale3d(1.15, 0.85, 1);
    }

    65% {
        transform: scale3d(0.95, 1.05, 1);
    }

    75% {
        transform: scale3d(1.05, 0.95, 1);
    }

    to {
        transform: scale3d(1, 1, 1);
    }
}

@keyframes swing {
    20% {
        transform: rotate3d(0, 0, 1, 15deg);
    }

    40% {
        transform: rotate3d(0, 0, 1, -10deg);
    }

    60% {
        transform: rotate3d(0, 0, 1, 5deg);
    }

    80% {
        transform: rotate3d(0, 0, 1, -5deg);
    }

    to {
        transform: rotate3d(0, 0, 1, 0deg);
    }
}

@keyframes head-shake {
    0% {
        transform: translateX(0);
    }

    6.5% {
        transform: translateX(-6px) rotateY(-9deg);
    }

    18.5% {
        transform: translateX(5px) rotateY(7deg);
    }

    31.5% {
        transform: translateX(-3px) rotateY(-5deg);
    }

    43.5% {
        transform: translateX(2px) rotateY(3deg);
    }

    50% {
        transform: translateX(0);
    }
}

@keyframes buzz {
    50% {
        transform: translateX(3px) rotate(2deg);
    }

    100% {
        transform: translateX(-3px) rotate(-2deg);
    }
}

@keyframes float {

    0%,
    100% {
        transform: translateY(0px);
    }

    50% {
        transform: translateY(-20px);
    }
}

@keyframes pulse-scale {

    0%,
    100% {
        transform: scale(1);
        opacity: 1;
    }

    50% {
        transform: scale(1.1);
        opacity: 0.7;
    }
}

@keyframes neon {

    0%,
    100% {
        text-shadow: 0 0 5px currentColor, 0 0 10px currentColor;
        filter: brightness(1);
    }

    50% {
        text-shadow: 0 0 10px currentColor, 0 0 20px currentColor, 0 0 30px currentColor;
        filter: brightness(1.2);
    }
}

/* Additional In/Out Animations */
@keyframes slide-in-right {
    from {
        transform: translateX(100%);
        opacity: 0;
    }

    to {
        transform: translateX(0);
        opacity: 1;
    }
}

@keyframes slide-out-left {
    from {
        transform: translateX(0);
        opacity: 1;
    }

    to {
        transform: translateX(-100%);
        opacity: 0;
    }
}

@keyframes slide-in-down {
    from {
        transform: translateY(-100%);
        opacity: 0;
    }

    to {
        transform: translateY(0);
        opacity: 1;
    }
}

@keyframes slide-out-down {
    from {
        transform: translateY(0);
        opacity: 1;
    }

    to {
        transform: translateY(100%);
        opacity: 0;
    }
}

@keyframes scale-in {
    from {
        transform: scale(0.8);
        opacity: 0;
    }

    to {
        transform: scale(1);
        opacity: 1;
    }
}

@keyframes scale-out {
    from {
        transform: scale(1);
        opacity: 1;
    }

    to {
        transform: scale(0.8);
        opacity: 0;
    }
}

@keyframes back-in-up {
    0% {
        transform: translateY(1200px) scale(0.7);
        opacity: 0.7;
    }

    80% {
        transform: translateY(0px) scale(0.7);
        opacity: 0.7;
    }

    100% {
        transform: scale(1);
        opacity: 1;
    }
}

@keyframes back-out-up {
    0% {
        transform: scale(1);
        opacity: 1;
    }

    20% {
        transform: translateY(0px) scale(0.7);
        opacity: 0.7;
    }

    100% {
        transform: translateY(-700px) scale(0.7);
        opacity: 0.7;
    }
}

@keyframes back-in-down {
    0% {
        transform: translateY(-1200px) scale(0.7);
        opacity: 0.7;
    }

    80% {
        transform: translateY(0px) scale(0.7);
        opacity: 0.7;
    }

    100% {
        transform: scale(1);
        opacity: 1;
    }
}

@keyframes back-out-down {
    0% {
        transform: scale(1);
        opacity: 1;
    }

    20% {
        transform: translateY(0px) scale(0.7);
        opacity: 0.7;
    }

    100% {
        transform: translateY(700px) scale(0.7);
        opacity: 0.7;
    }
}

@keyframes elastic-in {
    0% {
        transform: scale(0);
    }

    55% {
        transform: scale(1.05);
    }

    70% {
        transform: scale(0.95);
    }

    100% {
        transform: scale(1);
    }
}

@keyframes elastic-out {
    0% {
        transform: scale(1);
    }

    20% {
        transform: scale(0.9);
    }

    50%,
    55% {
        transform: scale(1.1);
    }

    100% {
        transform: scale(0);
    }
}

/* Specialized Entrance Effects */
@keyframes puff-in {
    0% {
        transform: scale(2);
        filter: blur(4px);
        opacity: 0;
    }

    100% {
        transform: scale(1);
        filter: blur(0px);
        opacity: 1;
    }
}

@keyframes vanish-in {
    0% {
        transform: scale(0);
        filter: blur(6px);
        opacity: 0;
    }

    100% {
        transform: scale(1);
        filter: blur(0px);
        opacity: 1;
    }
}

@keyframes swivel-horizontal {
    0% {
        transform: rotateY(-180deg);
        opacity: 0;
    }

    100% {
        transform: rotateY(0deg);
        opacity: 1;
    }
}

@keyframes swivel-vertical {
    0% {
        transform: rotateX(-180deg);
        opacity: 0;
    }

    100% {
        transform: rotateX(0deg);
        opacity: 1;
    }
}

/* Specialized Exit Effects */
@keyframes puff-out {
    0% {
        transform: scale(1);
        filter: blur(0px);
        opacity: 1;
    }

    100% {
        transform: scale(2);
        filter: blur(4px);
        opacity: 0;
    }
}

@keyframes vanish-out {
    0% {
        transform: scale(1);
        filter: blur(0px);
        opacity: 1;
    }

    100% {
        transform: scale(0);
        filter: blur(6px);
        opacity: 0;
    }
}

@keyframes swivel-horizontal-out {
    0% {
        transform: rotateY(0deg);
        opacity: 1;
    }

    100% {
        transform: rotateY(180deg);
        opacity: 0;
    }
}

@keyframes swivel-vertical-out {
    0% {
        transform: rotateX(0deg);
        opacity: 1;
    }

    100% {
        transform: rotateX(180deg);
        opacity: 0;
    }
}

@keyframes blur-out {
    0% {
        filter: blur(0px);
        opacity: 1;
    }

    100% {
        filter: blur(8px);
        opacity: 0;
    }
}

/* ===== ANIMATION UTILITY CLASSES ===== */

/* Emphasis Animations (mostly on hover) */
.cm.anim-pulse:hover,
.cm .anim-pulse:hover {
    animation: pulse-grow 0.5s ease-in-out;
}

.cm.anim-shake:hover,
.cm .anim-shake:hover {
    animation: shake-horizontal 0.8s cubic-bezier(.36, .07, .19, .97) both;
}

.cm.anim-tada:hover,
.cm .anim-tada:hover {
    animation: tada 1s ease;
}

.cm.anim-spin,
.cm .anim-spin {
    animation: spin 2s linear infinite;
}

.cm.anim-jiggle:hover,
.cm .anim-jiggle:hover {
    animation: jiggle 0.5s infinite;
}

.cm.anim-bounce:hover,
.cm .anim-bounce:hover {
    animation: bounce 1s ease;
}

.cm.anim-flash:hover,
.cm .anim-flash:hover {
    animation: flash 1s ease;
}

.cm.anim-wobble:hover,
.cm .anim-wobble:hover {
    animation: wobble 1s ease;
}

.cm.anim-heartbeat:hover,
.cm .anim-heartbeat:hover {
    animation: heartbeat 1.5s ease-in-out;
}

.cm.anim-forward:hover,
.cm .anim-forward:hover {
    transform: scale(1.02);
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25);
    transition: all 0.3s ease;
}

/* Additional Emphasis Animations */
.cm.anim-glow:hover,
.cm .anim-glow:hover {
    animation: glow 1s ease-in-out infinite alternate;
}

.cm.anim-rubber-band:hover,
.cm .anim-rubber-band:hover {
    animation: rubber-band 1s ease;
}

.cm.anim-swing:hover,
.cm .anim-swing:hover {
    animation: swing 1s ease;
    transform-origin: top center;
}

.cm.anim-head-shake:hover,
.cm .anim-head-shake:hover {
    animation: head-shake 1s ease-in-out;
}

.cm.anim-buzz:hover,
.cm .anim-buzz:hover {
    animation: buzz 0.15s infinite linear alternate;
}

.cm.anim-float,
.cm .anim-float {
    animation: float 3s ease-in-out infinite;
}

.cm.anim-pulse-scale:hover,
.cm .anim-pulse-scale:hover {
    animation: pulse-scale 1s ease-in-out infinite;
}

.cm.anim-neon:hover,
.cm .anim-neon:hover {
    animation: neon 1.5s ease-in-out infinite alternate;
}

