    animation: zoom-out 0.5s ease-in forwards;
}

.cm.anim-slide-in-left,
.cm .anim-slide-in-left {
    animation: slide-in-left 0.5s ease-out forwards;
}

.cm.anim-slide-out-right,
.cm .anim-slide-out-right {
    animation: slide-out-right 0.5s ease-in forwards;
}

.cm.anim-slide-in-top,
.cm .anim-slide-in-top {
    animation: slide-in-top 0.5s ease-out forwards;
}

.cm.anim-slide-out-top,
.cm .anim-slide-out-top {
