.cm .anim-puff-in {
    animation: puff-in 0.7s ease-out forwards;
}

.cm.anim-puff-out,
.cm .anim-puff-out {
    animation: puff-out 0.7s ease-in forwards;
}

.cm.anim-vanish-in,
.cm .anim-vanish-in {
    animation: vanish-in 0.6s ease-out forwards;
}

.cm.anim-vanish-out,
.cm .anim-vanish-out {
    animation: vanish-out 0.6s ease-in forwards;
}

.cm.anim-swivel-horizontal,
.cm .anim-swivel-horizontal {
    animation: swivel-horizontal 0.8s ease-out forwards;
    perspective: 800px;
}

.cm.anim-swivel-horizontal-out,
.cm .anim-swivel-horizontal-out {
    animation: swivel-horizontal-out 0.8s ease-in forwards;
    perspective: 800px;
}

.cm.anim-swivel-vertical,
.cm .anim-swivel-vertical {
    animation: swivel-vertical 0.8s ease-out forwards;
    perspective: 800px;
}

.cm.anim-swivel-vertical-out,
.cm .anim-swivel-vertical-out {
    animation: swivel-vertical-out 0.8s ease-in forwards;
    perspective: 800px;
}

.cm.anim-blur-out,
.cm .anim-blur-out {
    animation: blur-out 0.5s ease-in forwards;
}

/* ===== ANIMATION DURATION MODIFIERS ===== */
.cm.anim-duration-fast,
.cm .anim-duration-fast {
    animation-duration: 0.3s !important;
}

