 * CM ICON UTILITY SYSTEM
 * Modular icon system following CM design methodology
 * =================================
 */

/* =================================
 * Section 1: BASE ICON STYLES
 * ================================= */

/* Base styles for CM font icons */
.cm[class*="icon-"]:not([class*='-svg']):before {
    font-family: 'Material Symbols Outlined';
    font-weight: normal;
    font-style: normal;
    line-height: 1;
    letter-spacing: normal;
    text-transform: none;
    display: inline-block;
    white-space: nowrap;
    word-wrap: normal;
    direction: ltr;
    -webkit-font-feature-settings: 'liga';
    -webkit-font-smoothing: antialiased;
    vertical-align: middle;
    margin-top: -0.2em;
    font-size: inherit;
    /* Inherit from parent element */
    /* Hide decorative icons from screen readers */
    speak: none;
    speak-as: none;
}

/* Base styles for CM SVG icons */
.cm[class*="icon-"][class$="-svg"] {
    display: inline-block;
    width: 1.5rem;
    /* Default medium size */
    height: 1.5rem;
    background-color: currentColor;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
    -webkit-mask-size: contain;
    mask-size: contain;
    vertical-align: middle;
}



