/* =================================
 * Section 5: TRANSFORM MODIFIERS
 * ================================= */

.cm[class*="icon-"].rotate-90 {
    transform: rotate(90deg);
    display: inline-block;
}

.cm[class*="icon-"].rotate-180 {
    transform: rotate(180deg);
    display: inline-block;
}

.cm[class*="icon-"].rotate-270 {
    transform: rotate(270deg);
    display: inline-block;
}

.cm[class*="icon-"].flip-horizontal {
    transform: scaleX(-1);
    display: inline-block;
}

.cm[class*="icon-"].flip-vertical {
    transform: scaleY(-1);
    display: inline-block;
}

/* =================================
 * Section 6: ANIMATION MODIFIERS
 * ================================= */

.cm[class*="icon-"].spin {
    animation: cm-icon-spin 2s linear infinite;
}

.cm[class*="icon-"].pulse {
    animation: cm-icon-pulse 2s ease-in-out infinite alternate;
}

.cm[class*="icon-"].jiggle {
    animation: cm-icon-jiggle 0.5s ease-in-out infinite;
}

.cm[class*="icon-"].bounce {
    animation: cm-icon-bounce 1.5s infinite;
}

.cm[class*="icon-"].shake {
    animation: cm-icon-shake 0.82s cubic-bezier(.36, .07, .19, .97) both infinite;
    transform: translate3d(0, 0, 0);
    backface-visibility: hidden;
    perspective: 1000px;
}

@keyframes cm-icon-spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

@keyframes cm-icon-pulse {
    from {
        opacity: 1;
    }

    to {
        opacity: 0.5;
    }
}

@keyframes cm-icon-jiggle {

    0%,
    100% {
        transform: rotate(-3deg);
    }

    50% {
        transform: rotate(3deg);
    }
}

@keyframes cm-icon-bounce {

    0%,
    20%,
    50%,
    80%,
    100% {
        transform: translateY(0);
    }

    40% {
        transform: translateY(-10px);
    }

    60% {
        transform: translateY(-5px);
    }
}

@keyframes cm-icon-shake {

    10%,
    90% {
        transform: translate3d(-1px, 0, 0);
    }

    20%,
    80% {
        transform: translate3d(2px, 0, 0);
    }

    30%,
    50%,
    70% {
        transform: translate3d(-4px, 0, 0);
    }

    40%,
    60% {
        transform: translate3d(4px, 0, 0);
    }
}

/* =================================
 * Section 7: ACCESSIBILITY & STATES
 * ================================= */

/* Interactive states */
.cm[class*="icon-"].interactive {
    cursor: pointer;
    transition: color 0.2s ease, transform 0.2s ease;
}

.cm[class*="icon-"].interactive:hover {
    transform: scale(1.1);
}

.cm[class*="icon-"].interactive:active {
    transform: scale(0.95);
}

/* Disabled state */
.cm[class*="icon-"].disabled {
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
}

/* Screen reader support */
.cm[class*="icon-"][aria-hidden="false"] {
    speak: normal;
    speak-as: normal;
}

/* Focus indicator for keyboard navigation */
.cm[class*="icon-"]:focus {
    outline: 2px solid var(--cm-focus-color, var(--cm-blue));
    outline-offset: 2px;
}

/* ===== /public/css/cm-object-tooltips.css ===== */
/* =====================================================
   CM TOOLTIP OBJECT
   
   A comprehensive tooltip system built on Bootstrap's tooltip component with:
   - Two tooltip trigger styles: .tooltip-text (inline dashed) and .tooltip-list (badge-style)
   - Color modifiers for badges (primary, secondary, success, warning, danger, info, light, dark)
   - Tooltip popup color variants (danger, success, warning, info, primary)
   - Size variants (large, small) and shape variants (rounded, square)
   - Full accessibility support with keyboard navigation
   - Bootstrap integration with custom CM Design System colors
   ===================================================== */

/* ===== CM TOOLTIP SYSTEM ===== */
/* 
   Core tooltip variables and base trigger styles.
   Integrates with Bootstrap's tooltip component while using CM color system.
*/


/* Tooltip variables - all tooltips use dark grey permanently */
.tooltip {
    --bs-tooltip-bg: var(--cm-dark-grey-rgb) !important;
    --bs-tooltip-color: var(--cm-white-rgb) !important;
    --bs-tooltip-opacity: 1;
    --bs-tooltip-font-size: 0.875rem;
    --bs-tooltip-border-radius: 0.5rem;
    --bs-tooltip-padding-y: 0.75rem;
    --bs-tooltip-padding-x: 0.75rem;
    --bs-tooltip-max-width: 300px;
}

/* ===== TOOLTIP TRIGGER TYPES ===== */
/* 
   Two main tooltip trigger styles for different use cases:
   1. .tooltip.intext: Inline text with dashed underline (blends with content)
   2. .tooltip.listed: Badge-style standalone element (prominent display)
*/

/* Base tooltip trigger styles */
.cm-tooltip-trigger,
.cm.tooltip.intext,
.cm.tooltip.listed {
    cursor: help;
    text-decoration: none;
    position: relative;
}

/* Inline text tooltip - inherits parent styling with dashed underline 
   Usage: <span class="cm tooltip intext" data-bs-toggle="tooltip" title="Tooltip content">trigger text</span> */
.cm.tooltip.intext {
    color: inherit !important;
    font-weight: inherit;
    display: inline;
    border-bottom: 2px dashed currentColor;
    white-space: nowrap !important;
}

.cm.tooltip.intext:hover {
    color: inherit !important;
    text-decoration: none;
    border-bottom-style: solid;
}

/* Badge-style tooltip - standalone styled element 
   Usage: <span class="cm tooltip listed cm-primary" data-bs-toggle="tooltip" title="Tooltip content">Badge Text</span> */
.cm.tooltip.listed {
    display: inline-block;
    padding: 0.35em 0.65em;
    font-size: 0.875em;
    font-weight: 600;
    line-height: 1;
    text-align: center;
    white-space: nowrap;
    vertical-align: baseline;
    border-radius: 0.375rem;
    transition: opacity 0.15s ease-in-out;
    border: none !important;
    /* Default to dark grey color scheme */
    color: var(--cm-white-rgb) !important;
    background-color: var(--cm-dark-grey-rgb) !important;
}

.cm.tooltip.listed:hover {
    opacity: 0.85;
    color: var(--cm-white-rgb) !important;
    text-decoration: none;
}

/* ===== COLOR MODIFIER CLASSES FOR TOOLTIP BADGES ===== */
/* 
   Color modifiers for .tooltip.listed badge-style tooltips.
   These only affect the badge appearance, not the tooltip popup itself.
   
   Available colors: cm-primary, cm-secondary, cm-success, cm-warning, 
   cm-danger, cm-info, cm-light, cm-dark
   
   Usage: <span class="cm tooltip listed cm-success">Success Badge</span>
   Note: For tooltip popup colors, see TOOLTIP POPUP COLOR VARIANTS section below
*/

/* Primary color scheme */
.cm.tooltip.listed.cm-primary {
    color: var(--cm-white-rgb);
    background-color: var(--cm-dark-blue-rgb);
}

/* Secondary color scheme */
.cm.tooltip.listed.cm-secondary {
    color: var(--cm-white-rgb);
    background-color: var(--cm-dark-grey-rgb);
}

/* Success color scheme */
.cm.tooltip.listed.cm-success {
    color: var(--cm-white-rgb);
    background-color: var(--cm-green-rgb);
}

/* Warning color scheme */
.cm.tooltip.listed.cm-warning {
    color: var(--cm-black-rgb);
    /* Changed from dark-blue for better contrast */
    background-color: var(--cm-coral-rgb);
}

/* Danger color scheme */
.cm.tooltip.listed.cm-danger {
    color: var(--cm-white-rgb);
    background-color: var(--cm-red-rgb);
}

/* Info color scheme */
.cm.tooltip.listed.cm-info {
    color: var(--cm-white-rgb);
    background-color: var(--cm-teal-rgb);
}

/* Light color scheme */
.cm.tooltip.listed.cm-light {
    color: var(--cm-dark-blue-rgb);
    background-color: var(--cm-light-grey-rgb);
    border: 1px solid var(--cm-dark-grey-rgb);
}

/* Dark color scheme */
.cm.tooltip.listed.cm-dark {
    color: var(--cm-white-rgb);
    background-color: var(--cm-black-rgb);
}


/* Arrow styling for Bootstrap 5.3 - all arrows use dark grey permanently */
.tooltip .tooltip-arrow::before {
    border-color: var(--cm-dark-grey-rgb) !important;
}

/* Specific tooltip arrow colors based on placement */
.bs-tooltip-top .tooltip-arrow::before,
.bs-tooltip-auto[data-popper-placement^="top"] .tooltip-arrow::before {
    border-top-color: var(--cm-dark-grey-rgb) !important;
}

.bs-tooltip-end .tooltip-arrow::before,
.bs-tooltip-auto[data-popper-placement^="right"] .tooltip-arrow::before {
    border-right-color: var(--cm-dark-grey-rgb) !important;
}

.bs-tooltip-bottom .tooltip-arrow::before,
.bs-tooltip-auto[data-popper-placement^="bottom"] .tooltip-arrow::before {
    border-bottom-color: var(--cm-dark-grey-rgb) !important;
}

.bs-tooltip-start .tooltip-arrow::before,
.bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow::before {
    border-left-color: var(--cm-dark-grey-rgb) !important;
}

/* ===== TOOLTIP POPUP COLOR VARIANTS ===== */
/* 
   Color variants for the actual tooltip popup (not the trigger element).
   These classes are applied to the Bootstrap tooltip container to change 
   the background and text color of the tooltip popup itself.
   
   Available variants: tooltip-danger, tooltip-success, tooltip-warning, 
   tooltip-info, tooltip-primary
   
   Usage: Add class to trigger element, Bootstrap will apply to tooltip popup
   Example: <span data-bs-toggle="tooltip" class="tooltip-danger" title="Error message">Trigger</span>
*/

/* Danger tooltip variant */
.tooltip-danger .tooltip-inner,
.custom-tooltip-danger .tooltip-inner {
    background-color: var(--cm-red-rgb);
    color: var(--cm-white-rgb);
}

.tooltip-danger .tooltip-arrow::before,
.custom-tooltip-danger .tooltip-arrow::before {
    border-color: var(--cm-red-rgb);
}

/* Success tooltip variant */
.tooltip-success .tooltip-inner {
    background-color: var(--cm-green-rgb);
    color: var(--cm-white-rgb);
}

.tooltip-success .tooltip-arrow::before {
    border-color: var(--cm-green-rgb);
}

/* Warning tooltip variant */
.tooltip-warning .tooltip-inner {
    background-color: var(--cm-coral-rgb);
    color: var(--cm-dark-blue-rgb);
}

.tooltip-warning .tooltip-arrow::before {
    border-color: var(--cm-coral-rgb);
}

/* Info tooltip variant */
.tooltip-info .tooltip-inner {
    background-color: var(--cm-teal-rgb);
    color: var(--cm-white-rgb);
}

.tooltip-info .tooltip-arrow::before {
    border-color: var(--cm-teal-rgb);
}

/* Primary tooltip variant */
.tooltip-primary .tooltip-inner {
    background-color: var(--cm-dark-blue-rgb);
    color: var(--cm-white-rgb);
}

.tooltip-primary .tooltip-arrow::before {
    border-color: var(--cm-dark-blue-rgb);
}

/* ===== TOOLTIP SIZE VARIANTS ===== */
/* 
   Size modifiers for tooltip popups to accommodate different content lengths.
   
   Available sizes:
   - .tooltip-large: Larger font, more padding, max-width 400px
   - .tooltip-small: Smaller font, less padding, max-width 200px
   - Default: 0.875rem font, 0.75rem padding, max-width 300px
   
   Usage: Add class to trigger element for tooltip popup sizing
*/

.tooltip-large .tooltip-inner,
.custom-tooltip-large .tooltip-inner {
    font-size: 1.1rem;
    padding: 0.75rem 1rem;
    max-width: 400px;
}

.tooltip-small .tooltip-inner {
    font-size: 0.75rem;
    padding: 0.5rem 0.6rem;
    max-width: 200px;
}

/* ===== TOOLTIP SHAPE VARIANTS ===== */
/* 
   Shape modifiers for tooltip popup corners and appearance.
   
   Available shapes:
