/* 
   General tooltip and utility styles for star ratings, timelines, 
   color pickers, and other interactive elements
*/

/* Star rating styles */
.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #6c757d;
    /* Darker grey for better contrast */
    transition: color 0.2s;
}

.star:hover {
    color: #ffc107;
}

.star:focus {
    outline: 2px solid var(--cm-dark-blue-rgb);
    outline-offset: 2px;
    border-radius: 2px;
}

.rating {
    display: flex;
    gap: 0.25rem;
}

/* Timeline marker styles */
.timeline-marker {
    flex-shrink: 0;
}

/* Upload area hover effects */
.upload-area:hover {
    border-color: #007bff;
    background-color: #f8f9fa;
}

/* File item hover effects */
.file-item:hover {
    background-color: #f8f9fa;
}

/* Settings item hover effects */
.settings-item:hover {
    background-color: #f8f9fa;
}

/* Status indicator hover effects */
.status-indicator:hover {
    background-color: #f8f9fa;
}

/* Data point hover effects */
.data-point:hover {
    transform: scale(1.2);
    transition: transform 0.2s;
}

/* Color option hover effects */
.color-option:hover {
    transform: scale(1.1);
    transition: transform 0.2s;
}

/* Focus states for interactive elements */
.color-option:focus,
.data-point:focus,
.timeline-marker:focus {
    outline: 2px solid var(--cm-dark-blue-rgb);
    outline-offset: 2px;
}

/* High contrast mode support */
@media (prefers-contrast: high) {
    [data-bs-toggle="tooltip"]:focus {
        outline: 3px solid currentColor;
        outline-offset: 3px;
    }

    .cm.tooltip.listed {
        border: 1px solid currentColor;
    }
}

/* ===== /public/css/cm-object-callouts.css ===== */
/* =====================================================
   CM CALLOUT OBJECT
   
   A comprehensive callout/alert system with multiple styling options:
   - Base callout styles with left border accent
   - Color modifiers (red, jasper, tomato, coral, teal, etc.)
   - Semantic modifiers (primary, secondary, success, danger, warning, info)
   - Functional modifiers (advice, action, do, dont, feedback-pos, feedback-neg)
   - Heading-based styling (h2-h6 support)
   - Icon support and responsive behavior
   ===================================================== */


/* ===== CM CALLOUT VARIABLES ===== */
:root {
    /* Base Callout Variables */
    --cm-callout-padding-y: 1rem;
    --cm-callout-padding-x: 1.25rem;
    --cm-callout-color: var(--cm-dark-blue);
    --cm-callout-bg: var(--cm-white);
    --cm-callout-border-color: var(--cm-light-grey);
    --cm-callout-border-width: 1px;
    --cm-callout-border-radius: var(--cm-border-radius);
    --cm-callout-border-left-width: 4px;
    --cm-callout-border-left-color: var(--cm-primary);

    /* Callout Typography Variables */
    --cm-callout-font-size: 1rem;
    --cm-callout-line-height: 1.5;
    --cm-callout-font-weight: 400;

    /* Callout Icon Variables */
    --cm-callout-icon-size: 3rem;
    --cm-callout-icon-color: var(--cm-callout-border-left-color);
    --cm-callout-icon-margin: var(--cm-callout-padding-x);

    /* Callout Header Variables */
    --cm-callout-header-font-weight: 600;
    --cm-callout-header-margin-bottom: 0.5rem;
    --cm-callout-header-color: var(--cm-callout-border-left-color);
}

/* ===== BASE CALLOUT STYLES ===== */
.cm.callout {
    display: block;
    padding: var(--cm-callout-padding-y) var(--cm-callout-padding-x);
    margin: 0;
    background-color: var(--cm-callout-bg);
    border: var(--cm-callout-border-width) solid var(--cm-callout-border-left-color);
    border-left: var(--cm-callout-border-left-width) solid var(--cm-callout-border-left-color);
    border-radius: var(--cm-callout-border-radius);
    font-size: var(--cm-callout-font-size);
    line-height: var(--cm-callout-line-height);
    font-weight: var(--cm-callout-font-weight);
    color: var(--cm-callout-color);
    box-shadow: var(--cm-object-shadow);
}

.cm.callout:last-child {
    margin-bottom: 0;
}

/* Callout with icon */
.cm.callout.with-icon {
    display: flex;
    align-items: center;
    gap: var(--cm-callout-icon-margin);
}

.cm.callout .callout-icon {
    font-size: var(--cm-callout-icon-size);
    color: var(--cm-callout-border-left-color);
    flex-shrink: 0;
    line-height: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--cm-callout-icon-size);
    height: var(--cm-callout-icon-size);
    /* Set the following to 0 to initially hide icons to allow entrance animatio if one in place for callout icons */
    opacity: 1;
    transform: scale(1);
}

.cm.callout .callout-content {
    flex: 1;
}

/* Callout headers */
.cm.callout .callout-header {
    font-weight: var(--cm-callout-header-font-weight);
    margin-bottom: var(--cm-callout-header-margin-bottom);
    color: var(--cm-callout-header-color);
    margin-top: 0;
}

.cm.callout .callout-header.h2 {
    font-size: 1.5rem;
}

.cm.callout .callout-header.h3 {
    font-size: 1.25rem;
}

.cm.callout .callout-header.h4 {
    font-size: 1.125rem;
}

.cm.callout .callout-header.h5 {
    font-size: 1rem;
}

.cm.callout .callout-header.h6 {
    font-size: 0.875rem;
}

/* ===== HEADING-BASED CALLOUT STYLING (MATCHING ACCORDIONS) ===== */
/* 
   Automatic styling based on heading level within callouts.
   Matches the accordion heading theme system for design consistency.
   
   H2: Light blue background
   H3: Light grey background  
   H4: Dark grey background with white text
   H5: Dark blue background with white text
   H6: Minimal styling
   
   Usage: Headings inside callouts automatically get themed background colors.
   Border colors come from the default primary color or color modifier classes.
   Color modifiers (red, success, etc.) will override these backgrounds.
*/

/* H2 Callouts - Light blue background with black subtle border */
.cm.callout:has(h2) {
    --cm-callout-bg: var(--cm-light-blue);
    --cm-callout-color: var(--cm-black-subtle);
    --cm-callout-border-left-color: var(--cm-black-subtle);
    --cm-callout-header-color: var(--cm-black-subtle);
}

/* H3 Callouts - Light grey background with black subtle border */
.cm.callout:has(h3) {
    --cm-callout-bg: var(--cm-light-grey);
    --cm-callout-color: var(--cm-black-subtle);
    --cm-callout-border-left-color: var(--cm-black-subtle);
    --cm-callout-header-color: var(--cm-black-subtle);
}

/* H4 Callouts - Dark grey background with black subtle border */
.cm.callout:has(h4) {
    --cm-callout-bg: var(--cm-dark-grey);
    --cm-callout-color: var(--cm-white);
    --cm-callout-border-left-color: var(--cm-black-subtle);
    --cm-callout-header-color: var(--cm-white);
}

/* H5 Callouts - Dark blue background with black subtle border */
.cm.callout:has(h5) {
    --cm-callout-bg: var(--cm-dark-blue);
    --cm-callout-color: var(--cm-white);
    --cm-callout-border-left-color: var(--cm-black-subtle);
    --cm-callout-header-color: var(--cm-white);
}

/* H6 Callouts - Minimal style with black subtle border */
.cm.callout:has(h6) {
    --cm-callout-border-left-color: var(--cm-black-subtle);
    --cm-callout-header-color: var(--cm-black-subtle);
}

