    --cm-callout-bg: var(--cm-info-light);
}

.cm.callout.light {
    --cm-callout-border-left-color: var(--cm-dark-grey);
    --cm-callout-bg: var(--cm-light);
}

.cm.callout.dark {
    --cm-callout-border-left-color: var(--cm-dark);
    --cm-callout-bg: color-mix(in srgb, var(--cm-dark) 5%, var(--cm-white) 95%);
}

/* ===== FUNCTIONAL CALLOUT MODIFIERS ===== */
/* 
   Content-specific modifiers for educational and instructional contexts.
   Designed for learning materials, documentation, and user guidance.
   
   Available modifiers:
   - .warning: Important warnings (red)
   - .advice: Helpful advice (green) 
   - .action: Action items/tasks (teal)
   - .starting: Getting started content (coral)
   - .do: Best practices (green)
   - .dont: Things to avoid (red)
   - .feedback-pos: Positive feedback (green)
   - .feedback-neg: Negative feedback (red)
   
   Usage: <div class="cm callout advice">Helpful tip content</div>
*/

.cm.callout.warning {
    --cm-callout-border-left-color: var(--cm-red);
    --cm-callout-bg: color-mix(in srgb, var(--cm-red) 5%, var(--cm-white) 95%);
}

.cm.callout.advice {
    --cm-callout-border-left-color: var(--cm-green);
    --cm-callout-bg: color-mix(in srgb, var(--cm-green) 5%, var(--cm-white) 95%);
}

.cm.callout.action {
    --cm-callout-border-left-color: var(--cm-teal);
    --cm-callout-bg: color-mix(in srgb, var(--cm-teal) 5%, var(--cm-white) 95%);
}

.cm.callout.starting {
    --cm-callout-border-left-color: var(--cm-coral);
    --cm-callout-bg: color-mix(in srgb, var(--cm-coral) 5%, var(--cm-white) 95%);
}

.cm.callout.do {
    --cm-callout-border-left-color: var(--cm-green);
    --cm-callout-bg: color-mix(in srgb, var(--cm-green) 5%, var(--cm-white) 95%);
}

.cm.callout.dont {
    --cm-callout-border-left-color: var(--cm-red);
    --cm-callout-bg: color-mix(in srgb, var(--cm-red) 5%, var(--cm-white) 95%);
}

.cm.callout.feedback-pos {
    --cm-callout-border-left-color: var(--cm-green);
    --cm-callout-bg: color-mix(in srgb, var(--cm-green) 5%, var(--cm-white) 95%);
}

.cm.callout.feedback-neg {
    --cm-callout-border-left-color: var(--cm-red);
    --cm-callout-bg: color-mix(in srgb, var(--cm-red) 5%, var(--cm-white) 95%);
}

/* ===== RESPONSIVE BEHAVIOR ===== */
/* 
   Responsive adjustments for callouts with icons and width modifiers.
   Ensures optimal layout and readability across different screen sizes.
*/

/* Medium breakpoint: icon at top, 40% max width when floated */
@media (min-width: 768px) and (max-width: 991px) {
    .cm.callout.with-icon.width-40 {
        max-width: 40% !important;
    }

    .cm.callout.with-icon.width-40-right {
        width: 40% !important;
    }

    .cm.callout.with-icon {
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .cm.callout .callout-icon {
        margin-bottom: 0;
    }

    .cm.callout .callout-content {
        width: 100%;
    }
}

/* Large breakpoint and up: icon to left, 40% max width when floated */
@media (min-width: 992px) {
    .cm.callout.with-icon.width-40 {
        max-width: 40% !important;
    }

    .cm.callout.with-icon.width-40-right {
        width: 40% !important;
    }
}

/* Small breakpoints: smaller icons, normal layout */
@media (max-width: 576px) {
    .cm.callout {
        --cm-callout-padding-x: 1rem;
        --cm-callout-padding-y: 0.875rem;
    }

    .cm.callout.with-icon {
