    --cm-accordion-border-radius: var(--cm-border-radius);
    --cm-accordion-inner-border-radius: calc(var(--cm-accordion-border-radius) - var(--cm-accordion-border-width));
    --cm-accordion-body-padding-y: 0;
    --cm-accordion-body-padding-x: 0;
    --cm-accordion-active-color: var(--cm-primary);
