    /* Accordion heading typography variables - automatically inherit from global headings 
       Note: Each heading level (h1-h6) has individual variables for maximum flexibility
       These support the heading-specific themes defined later in this file */
    --cm-accordion-h1-font-size: var(--cm-h1-font-size);
    --cm-accordion-h1-font-weight: 500;
    --cm-accordion-h1-line-height: 1.2;
    --cm-accordion-h1-margin-top: 0;
    --cm-accordion-h1-margin-bottom: 0.5rem;

    --cm-accordion-h2-font-size: var(--cm-h2-font-size);
    --cm-accordion-h2-font-weight: 500;
    --cm-accordion-h2-line-height: 1.2;
    --cm-accordion-h2-margin-top: 0;
    --cm-accordion-h2-margin-bottom: 0.5rem;

    --cm-accordion-h3-font-size: var(--cm-h3-font-size);
    --cm-accordion-h3-font-weight: 500;
    --cm-accordion-h3-line-height: 1.2;
    --cm-accordion-h3-margin-top: 0;
    --cm-accordion-h3-margin-bottom: 0.5rem;

    --cm-accordion-h4-font-size: var(--cm-h4-font-size);
    --cm-accordion-h4-font-weight: 500;
    --cm-accordion-h4-line-height: 1.2;
    --cm-accordion-h4-margin-top: 0;
    --cm-accordion-h4-margin-bottom: 0.5rem;

    --cm-accordion-h5-font-size: var(--cm-h5-font-size);
    --cm-accordion-h5-font-weight: 500;
    --cm-accordion-h5-line-height: 1.2;
    --cm-accordion-h5-margin-top: 0;
    --cm-accordion-h5-margin-bottom: 0.5rem;

    --cm-accordion-h6-font-size: var(--cm-h6-font-size);
    --cm-accordion-h6-font-weight: 500;
    --cm-accordion-h6-line-height: 1.2;
    --cm-accordion-h6-margin-top: 0;
    --cm-accordion-h6-margin-bottom: 0.5rem;
    --cm-accordion-button-color: var(--cm-accordion-color);
    --cm-accordion-button-bg: var(--cm-accordion-bg);
    --cm-accordion-button-active-color: var(--cm-accordion-active-color);
    --cm-accordion-button-active-bg: var(--cm-accordion-active-bg);
    --cm-accordion-button-focus-border-color: var(--cm-primary);
    --cm-accordion-button-focus-box-shadow: 0 0 0 0.2rem rgba(var(--cm-primary-rgb), 0.75);

    /* Accordion Icon Variables */
    --cm-accordion-button-icon: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='currentColor'%3e%3cpath fill-rule='evenodd' d='M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708z'/%3e%3c/svg%3e");
    --cm-accordion-button-icon-width: 1.25rem;
    --cm-accordion-button-icon-transform: rotate(-180deg);
    --cm-accordion-button-icon-transition: transform 0.2s ease-in-out;

    /* Flush Accordion Variables */
    --cm-accordion-flush-bg: transparent;
    --cm-accordion-flush-border-color: transparent;

    /* Accordion Transition */
    --cm-accordion-transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out, border-radius 0.15s ease;

    /* Accordion Color Overrides using CM colors */
    --cm-accordion-bg: var(--cm-white);
