    --cm-accordion-button-color: var(--cm-dark-blue);
    --cm-accordion-button-bg: var(--cm-white);
    --cm-accordion-button-active-color: var(--cm-primary);
    --cm-accordion-button-active-bg: var(--cm-white-subtle);
    --cm-accordion-button-focus-border-color: var(--cm-primary);
    --cm-accordion-body-color: var(--cm-text);
}

/* ===== CM ACCORDION BASE STYLES ===== */
.cm.accordion {
    --bs-accordion-color: var(--cm-accordion-color);
    --bs-accordion-bg: var(--cm-accordion-bg);
    --bs-accordion-transition: var(--cm-accordion-transition);
    --bs-accordion-border-color: var(--cm-accordion-border-color);
    --bs-accordion-border-width: var(--cm-accordion-border-width);
    --bs-accordion-border-radius: var(--cm-accordion-border-radius);
    --bs-accordion-inner-border-radius: var(--cm-accordion-inner-border-radius);
    --bs-accordion-btn-padding-x: var(--cm-accordion-button-padding-x);
    --bs-accordion-btn-padding-y: var(--cm-accordion-button-padding-y);
    --bs-accordion-btn-color: var(--cm-accordion-button-color);
    --bs-accordion-btn-bg: var(--cm-accordion-button-bg);
    --bs-accordion-btn-icon: var(--cm-accordion-button-icon);
    --bs-accordion-btn-icon-width: var(--cm-accordion-button-icon-width);
    --bs-accordion-btn-icon-transform: var(--cm-accordion-button-icon-transform);
    --bs-accordion-btn-icon-transition: var(--cm-accordion-button-icon-transition);
    --bs-accordion-btn-active-icon: var(--cm-accordion-button-icon);
    --bs-accordion-btn-focus-border-color: var(--cm-accordion-button-focus-border-color);
    --bs-accordion-btn-focus-box-shadow: var(--cm-accordion-button-focus-box-shadow);
    --bs-accordion-body-padding-x: var(--cm-accordion-body-padding-x);
    --bs-accordion-body-padding-y: var(--cm-accordion-body-padding-y);
    --bs-accordion-active-color: var(--cm-accordion-button-active-color);
    --bs-accordion-active-bg: var(--cm-accordion-button-active-bg);
}

/* Accordion Item */
.cm.accordion .accordion-item {
    color: var(--cm-accordion-color);
    background-color: transparent;
    border: none;
    border-radius: 0;
    margin-bottom: 1rem;
    box-shadow: none;
    overflow: hidden;
}

.cm.accordion .accordion-item:last-child {
    margin-bottom: 0;
}

.cm.accordion .accordion-item:first-of-type {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
}

.cm.accordion .accordion-item:first-of-type .accordion-button {
    border-top-left-radius: var(--cm-accordion-inner-border-radius);
    border-top-right-radius: var(--cm-accordion-inner-border-radius);
}

.cm.accordion .accordion-item:not(:first-of-type) {
    border-top: none;
}

.cm.accordion .accordion-item:last-of-type {
    border-bottom-right-radius: 0;
    border-bottom-left-radius: 0;
}

.cm.accordion .accordion-item:last-of-type .accordion-button.collapsed {
    border-bottom-right-radius: var(--cm-accordion-inner-border-radius);
    border-bottom-left-radius: var(--cm-accordion-inner-border-radius);
}

.cm.accordion .accordion-item:last-of-type .accordion-collapse {
    border-bottom-right-radius: 0;
    border-bottom-left-radius: 0;
}

/* Accordion Header */
.cm.accordion .accordion-header {
    margin-bottom: 0;
    font-size: 1rem;
    font-weight: 400;
    line-height: 1.5;
}

/* Accordion Button */
.cm.accordion .accordion-button {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
    padding: var(--cm-accordion-button-padding-y) var(--cm-accordion-button-padding-x);
    font-size: 1rem;
    color: var(--cm-accordion-button-color);
    text-align: left;
    background-color: var(--cm-accordion-button-bg);
    border: 0;
    border-radius: 0;
    overflow-anchor: none;
    transition: var(--cm-accordion-transition);
}

.cm.accordion .accordion-button:not(.collapsed) {
    color: var(--cm-accordion-button-active-color);
    background-color: var(--cm-accordion-button-active-bg);
    box-shadow: inset 0 calc(-1 * var(--cm-accordion-border-width)) 0 var(--cm-accordion-border-color);
}

.cm.accordion .accordion-button:not(.collapsed)::after {
    background-image: var(--cm-accordion-button-icon);
    transform: var(--cm-accordion-button-icon-transform);
}

.cm.accordion .accordion-button::after {
    flex-shrink: 0;
    width: var(--cm-accordion-button-icon-width);
    height: var(--cm-accordion-button-icon-width);
    margin-left: auto;
    content: "";
    background-image: var(--cm-accordion-button-icon);
    background-repeat: no-repeat;
    background-size: var(--cm-accordion-button-icon-width);
    transition: var(--cm-accordion-button-icon-transition);
}

.cm.accordion .accordion-button:hover {
    z-index: 2;
    background-color: color-mix(in srgb, var(--cm-accordion-button-bg) 95%, var(--cm-primary) 5%);
    transition: var(--cm-accordion-transition);
}

.cm.accordion .accordion-button:focus {
    z-index: 3;
    border-color: var(--cm-accordion-button-focus-border-color);
    outline: 0;
    box-shadow: var(--cm-accordion-button-focus-box-shadow);
}

.cm.accordion .accordion-button:focus-visible {
    outline: 2px solid var(--cm-primary);
    outline-offset: 2px;
}

.cm.accordion .accordion-button:active {
    background-color: color-mix(in srgb, var(--cm-accordion-button-bg) 90%, var(--cm-primary) 10%);
}

.cm.accordion .accordion-button:disabled {
    color: var(--cm-disabled-text);
    background-color: var(--cm-disabled);
    opacity: var(--cm-disabled-opacity);
    cursor: not-allowed;
}

.cm.accordion .accordion-button:disabled::after {
    opacity: var(--cm-disabled-opacity);
}

/* Accordion Body */
.cm.accordion .accordion-body {
    padding: 1rem 0 1rem 0;
    color: var(--cm-accordion-body-color);
    background-color: transparent;
    line-height: 1.6;
    border: none;
    box-shadow: none;
}

.cm.accordion .accordion-body strong {
    color: var(--cm-dark-blue);
}

.cm.accordion .accordion-body code {
    background-color: var(--cm-light-blue);
    color: var(--cm-dark-blue);
    padding: 0.125rem 0.25rem;
    border-radius: var(--cm-border-radius);
}

/* Accordion Collapse */
.cm.accordion .accordion-collapse {
    border: solid var(--cm-accordion-border-color);
    border-width: 0;
    border-top: 1px solid rgba(var(--cm-light-blue-rgb), 0.5);
    transition: all 0.2s ease-in-out;
}

.cm.accordion .accordion-collapse.collapsing {
    transition: height 0.35s ease;
}

/* ===== ACCESSIBILITY ENHANCEMENTS ===== */

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {

    .cm.accordion .accordion-button,
    .cm.accordion .accordion-button::after,
    .accordion-button,
    .accordion-button::after,
    .cm.accordion .accordion-collapse,
    .accordion-collapse,
    .cm.accordion .accordion-collapse.collapsing,
    .accordion-collapse.collapsing {
        transition: none;
    }
}

/* High Contrast Mode Support */
@media (prefers-contrast: high) {
    .cm.accordion .accordion-item {
        border-width: 0;
    }

    .cm.accordion .accordion-button:focus {
        outline: 3px solid;
        outline-offset: 2px;
    }

    .cm.accordion .accordion-button:focus-visible {
        outline-width: 3px;
        outline-offset: 3px;
    }
}

/* Windows High Contrast Mode Support */
@media (forced-colors: active) {
    .cm.accordion .accordion-item {
        border: none;
        background-color: transparent;
    }

    .cm.accordion .accordion-button {
        background-color: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
    }

    .cm.accordion .accordion-button:hover,
    .cm.accordion .accordion-button:focus {
        background-color: Highlight;
        color: HighlightText;
        border-color: HighlightText;
        box-shadow: none;
    }

    .cm.accordion .accordion-button:not(.collapsed) {
        background-color: Canvas;
        color: CanvasText;
        border-color: CanvasText;
    }

    .cm.accordion .accordion-button:disabled {
        background-color: ButtonFace;
        color: GrayText;
        border-color: GrayText;
    }

    .cm.accordion .accordion-body {
        background-color: Canvas;
        color: CanvasText;
        border: none;
    }
}

/* Touch target size for mobile accessibility */
@media (max-width: 768px) {
    .cm.accordion .accordion-button {
        min-height: 44px;
        padding: 1rem 1.25rem;
    }
}

/* Enhanced keyboard navigation */
.cm.accordion .accordion-button:focus-visible {
    z-index: 4;
    position: relative;
}

/* Screen reader only text support */
.cm.accordion .sr-only,
.cm.accordion .visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Improve icon visibility for screen readers */
.cm.accordion .accordion-button::after {
    /* Icon is decorative and handled by aria-expanded */
    speak: none;
}

/* Improve readability and scanability */
.cm.accordion .accordion-body {
    line-height: 1.6;
}

.cm.accordion .accordion-body p:last-child {
    margin-bottom: 0;
}

/* Focus trap support for complex accordion content */
.cm.accordion .accordion-body:focus {
    outline: 2px solid var(--cm-primary);
    outline-offset: -2px;
}

/* Better visual hierarchy in accordion content */
.cm.accordion .accordion-body h1,
.cm.accordion .accordion-body h2,
.cm.accordion .accordion-body h3,
.cm.accordion .accordion-body h4,
.cm.accordion .accordion-body h5,
.cm.accordion .accordion-body h6 {
    margin-top: 0;
    margin-bottom: 0.75rem;
    color: var(--cm-dark-blue);
}



/* ===== CM ACCORDION MODIFIERS ===== */
/* Flush Accordion */
.cm.accordion.accordion-flush .accordion-collapse {
    border-width: 0;
}

.cm.accordion.accordion-flush .accordion-item {
    border-right: none;
    border-left: none;
    border-radius: 0;
}

.cm.accordion.accordion-flush .accordion-item:first-child {
    border-top: none;
}

.cm.accordion.accordion-flush .accordion-item:last-child {
    border-bottom: none;
}

.cm.accordion.accordion-flush .accordion-item .accordion-button,
.cm.accordion.accordion-flush .accordion-item .accordion-button.collapsed {
