    font-size: 1.25rem;
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: var(--cm-border-radius);
    transition: all 0.2s ease-in-out;
    position: relative;
}

.cm.accordion h2 .accordion-button:not(.collapsed),
.cm.accordion h3 .accordion-button:not(.collapsed),
.cm.accordion h4 .accordion-button:not(.collapsed),
.cm.accordion h5 .accordion-button:not(.collapsed) {
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
}

/* ===== SHARED ACCORDION ICON STYLES ===== */
.cm.accordion h2 .accordion-button::after,
.cm.accordion h3 .accordion-button::after,
.cm.accordion h4 .accordion-button::after,
.cm.accordion h5 .accordion-button::after {
