    width: 1.25rem;
    height: 1.25rem;
    margin-left: auto;
    flex-shrink: 0;
}

.cm.accordion h2 .accordion-button:not(.collapsed)::after,
.cm.accordion h3 .accordion-button:not(.collapsed)::after,
.cm.accordion h4 .accordion-button:not(.collapsed)::after,
.cm.accordion h5 .accordion-button:not(.collapsed)::after {
    transform: rotate(-180deg);
}

/* ===== HEADING-BASED THEME SYSTEM ===== */
/* Each heading level (H2-H6) has a unique color theme for visual hierarchy */

/* ===== H2 ACCORDION (BLUE THEME) ===== */
.cm.accordion h2 .accordion-button {
    background-color: var(--cm-light-blue);
    color: var(--cm-black-subtle);
