/* ===== /public/css/cm-object-buttons.css ===== */
/* =====================================================
   CM BUTTON OBJECT - CLEANED VERSION
   
   This file contains the essential button system including:
   - Base button styles and variables
   - Bootstrap-compatible button classes (btn-primary, btn-outline-primary, etc.)
   - CM custom color buttons (red, jasper, bronze, etc.)
   - CM custom outline buttons (outline-red, outline-jasper, etc.)
   - Button sizes and states
   - Responsive and accessibility features
   ===================================================== */

/* ===== CM BUTTON VARIABLES ===== */
:root {
    /* Base Button Variables */
    --cm-btn-padding-y: 0.375rem;
    --cm-btn-padding-x: 0.75rem;
    --cm-btn-font-family: var(--bs-font-sans-serif);
    --cm-btn-font-size: clamp(1rem, calc(1.275*var(--cmet-body-font-size)), 1.375rem);
    --cm-btn-font-weight: 400;
    --cm-btn-line-height: 1.5;
    --cm-btn-color: var(--cm-text);
    --cm-btn-bg: transparent;
    --cm-btn-border-width: var(--bs-border-width);
    --cm-btn-border-color: transparent;
    --cm-btn-border-radius: var(--bs-border-radius);
    --cm-btn-box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15), 0 1px 1px rgba(0, 0, 0, 0.075);
    --cm-btn-disabled-opacity: var(--cm-disabled-opacity);
    --cm-btn-focus-box-shadow: 0 0 0 0.2rem rgba(var(--cm-btn-focus-shadow-rgb), 0.5);

    /* Button Focus Variables */
    --cm-btn-focus-shadow-rgb: 10, 42, 61;

    /* Button Active Variables */
    --cm-btn-active-box-shadow: inset 0 3px 5px rgba(0, 0, 0, 0.125);

    /* Button Disabled Variables */
    --cm-btn-disabled-color: var(--cm-disabled-text);
    --cm-btn-disabled-bg: transparent;
    --cm-btn-disabled-border-color: transparent;

    /* Button Link Variables */
    --cm-btn-link-color: var(--cm-link);
    --cm-btn-link-hover-color: var(--cm-link-hover);
    --cm-btn-link-disabled-color: var(--cm-disabled-text);

    /* Button Sizes */
    --cm-btn-padding-y-sm: 0.25rem;
    --cm-btn-padding-x-sm: 0.5rem;
    --cm-btn-font-size-sm: var(--bs-small-font-size);
    --cm-btn-border-radius-sm: var(--bs-border-radius-sm);

    --cm-btn-padding-y-lg: 0.5rem;
    --cm-btn-padding-x-lg: 1rem;
    --cm-btn-font-size-lg: var(--bs-font-size-lg);
    --cm-btn-border-radius-lg: var(--bs-border-radius-lg);

    /* Primary Button Variables */
    --cm-btn-primary-color: var(--cm-primary-contrast);
    --cm-btn-primary-bg: var(--cm-primary);
    --cm-btn-primary-border-color: var(--cm-primary);
    --cm-btn-primary-hover-color: var(--cm-primary-contrast);
    --cm-btn-primary-hover-bg: var(--cm-primary-hover);
    --cm-btn-primary-hover-border-color: var(--cm-primary-hover);
    --cm-btn-primary-focus-shadow-rgb: 10, 42, 61;
    --cm-btn-primary-active-color: var(--cm-primary-contrast);
    --cm-btn-primary-active-bg: var(--cm-primary-active);
    --cm-btn-primary-active-border-color: var(--cm-primary-active);
    --cm-btn-primary-disabled-color: var(--cm-primary-contrast);
    --cm-btn-primary-disabled-bg: var(--cm-primary);
    --cm-btn-primary-disabled-border-color: var(--cm-primary);

    /* Secondary Button Variables */
    --cm-btn-secondary-color: var(--cm-secondary-contrast);
    --cm-btn-secondary-bg: var(--cm-secondary);
    --cm-btn-secondary-border-color: var(--cm-secondary);
    --cm-btn-secondary-hover-color: var(--cm-secondary-contrast);
    --cm-btn-secondary-hover-bg: var(--cm-secondary-hover);
    --cm-btn-secondary-hover-border-color: var(--cm-secondary-hover);
    --cm-btn-secondary-focus-shadow-rgb: 109, 109, 109;
    --cm-btn-secondary-active-color: var(--cm-secondary-contrast);
    --cm-btn-secondary-active-bg: var(--cm-secondary-active);
    --cm-btn-secondary-active-border-color: var(--cm-secondary-active);
    --cm-btn-secondary-disabled-color: var(--cm-secondary-contrast);
    --cm-btn-secondary-disabled-bg: var(--cm-secondary);
    --cm-btn-secondary-disabled-border-color: var(--cm-secondary);
}

/* ===== CM BUTTON BASE STYLES ===== */
.cm.btn {
    display: inline-block;
    font-family: var(--cm-btn-font-family);
