/* ===============================================
   CM CARD SYSTEM
   =============================================== */

/* ===== BASE CARD VARIABLES ===== */
.cm.card {
    /* Core Card Variables */
    --cm-card-spacer-y: 1rem;
    --cm-card-spacer-x: 1rem;
    --cm-card-title-spacer-y: 0.5rem;
    --cm-card-title-color: var(--cm-black);
    --cm-card-subtitle-color: var(--cm-dark-grey);
    --cm-card-border-width: 1px;
    --cm-card-border-color: rgba(0, 0, 0, 0.125);
    --cm-card-border-radius: 0.375rem;
    --cm-card-box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
    --cm-card-inner-border-radius: calc(var(--cm-card-border-radius) - var(--cm-card-border-width));
    --cm-card-cap-padding-y: var(--cm-card-spacer-y);
    --cm-card-cap-padding-x: var(--cm-card-spacer-x);
    --cm-card-cap-bg: var(--cm-light-grey);
    --cm-card-cap-color: var(--cm-black);
    --cm-card-height: auto;
    --cm-card-color: var(--cm-black);
    --cm-card-bg: var(--cm-white);
    --cm-card-img-overlay-padding: 1rem;
    --cm-card-group-margin: 0.75rem;

    /* Bootstrap Integration */
    --bs-card-spacer-y: var(--cm-card-spacer-y);
    --bs-card-spacer-x: var(--cm-card-spacer-x);
    --bs-card-title-spacer-y: var(--cm-card-title-spacer-y);
    --bs-card-title-color: var(--cm-card-title-color);
    --bs-card-subtitle-color: var(--cm-card-subtitle-color);
    --bs-card-border-width: var(--cm-card-border-width);
    --bs-card-border-color: var(--cm-card-border-color);
    --bs-card-border-radius: var(--cm-card-border-radius);
    --bs-card-box-shadow: var(--cm-card-box-shadow);
    --bs-card-inner-border-radius: var(--cm-card-inner-border-radius);
    --bs-card-cap-padding-y: var(--cm-card-cap-padding-y);
    --bs-card-cap-padding-x: var(--cm-card-cap-padding-x);
    --bs-card-cap-bg: var(--cm-card-cap-bg);
    --bs-card-cap-color: var(--cm-card-cap-color);
    --bs-card-height: var(--cm-card-height);
    --bs-card-color: var(--cm-card-color);
    --bs-card-bg: var(--cm-card-bg);
    --bs-card-img-overlay-padding: var(--cm-card-img-overlay-padding);
    --bs-card-group-margin: var(--cm-card-group-margin);
}

/* ===== BASE CARD STYLES ===== */
.cm.card {
    --bs-card-bg: var(--cm-card-bg);
    --bs-card-color: var(--cm-card-color);
    position: relative;
    display: flex;
    flex-direction: column;
    min-width: 0;
    height: var(--cm-card-height);
    color: var(--cm-card-color);
    word-wrap: break-word;
    background-color: var(--cm-card-bg);
    background-clip: border-box;
    border: var(--cm-card-border-width) solid var(--cm-card-border-color);
    border-radius: var(--cm-card-border-radius);
    box-shadow: var(--cm-card-box-shadow);
}

.cm.card>hr {
    margin-right: 0;
    margin-left: 0;
}

.cm.card>.list-group {
    border-top: inherit;
    border-bottom: inherit;
}

.cm.card>.list-group:first-child {
    border-top-width: 0;
    border-top-left-radius: var(--cm-card-inner-border-radius);
    border-top-right-radius: var(--cm-card-inner-border-radius);
}

.cm.card>.list-group:last-child {
    border-bottom-width: 0;
    border-bottom-right-radius: var(--cm-card-inner-border-radius);
    border-bottom-left-radius: var(--cm-card-inner-border-radius);
}

.cm.card>.card-header+.list-group,
.cm.card>.list-group+.card-footer {
    border-top: 0;
}

/* ===== CARD COMPONENTS ===== */

/* Card Body */
.cm.card .card-body {
    flex: 1 1 auto;
    padding: var(--cm-card-spacer-y) var(--cm-card-spacer-x);
    color: var(--cm-card-color);
}

/* Card Title and Subtitle */
.cm.card .card-title {
    margin-bottom: var(--cm-card-title-spacer-y);
    color: var(--cm-card-title-color);
    font-weight: 600;
}

.cm.card .card-subtitle {
    margin-top: calc(-0.5 * var(--cm-card-title-spacer-y));
    margin-bottom: 0;
    color: var(--cm-card-subtitle-color);
}

/* Card Text */
.cm.card .card-text:last-child {
    margin-bottom: 0;
}

/* Card Links with enhanced accessibility */
.cm.card .card-link {
    color: var(--cm-blue);
    text-decoration: none;
    border-radius: 0.25rem;
    padding: 0.125rem 0.25rem;
    margin: -0.125rem -0.25rem;
    transition: all 0.15s ease-in-out;
}

.cm.card .card-link:hover,
.cm.card .card-link:focus {
    color: var(--cm-blue);
    text-decoration: underline;
    background-color: color-mix(in srgb, var(--cm-blue) 10%, transparent);
}

.cm.card .card-link:focus {
    outline: 2px solid var(--cm-blue);
    outline-offset: 2px;
}

.cm.card .card-link+.card-link {
    margin-left: var(--cm-card-spacer-x);
}

/* Card Header and Footer */
.cm.card .card-header {
    padding: var(--cm-card-cap-padding-y) var(--cm-card-cap-padding-x);
    margin-bottom: 0;
    color: var(--cm-card-cap-color);
    background-color: var(--cm-card-cap-bg);
    border-bottom: var(--cm-card-border-width) solid var(--cm-card-border-color);
    border-top-left-radius: var(--cm-card-inner-border-radius);
    border-top-right-radius: var(--cm-card-inner-border-radius);
}

/* Remove margin-bottom from headings in card headers */
.cm.card .card-header h1,
.cm.card .card-header h2,
.cm.card .card-header h3,
.cm.card .card-header h4,
.cm.card .card-header h5,
.cm.card .card-header h6 {
    margin-bottom: 0;
}

.cm.card .card-footer {
    padding: var(--cm-card-cap-padding-y) var(--cm-card-cap-padding-x);
    color: var(--cm-card-cap-color);
    background-color: var(--cm-card-cap-bg);
    border-top: var(--cm-card-border-width) solid var(--cm-card-border-color);
    border-bottom-right-radius: var(--cm-card-inner-border-radius);
    border-bottom-left-radius: var(--cm-card-inner-border-radius);
}

/* Card Images */
.cm.card .card-img-overlay {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    padding: var(--cm-card-img-overlay-padding);
    border-radius: var(--cm-card-inner-border-radius);
}

.cm.card .card-img,
.cm.card .card-img-top,
.cm.card .card-img-bottom {
    width: 100%;
}

.cm.card .card-img,
.cm.card .card-img-top {
    border-top-left-radius: var(--cm-card-inner-border-radius);
    border-top-right-radius: var(--cm-card-inner-border-radius);
}

.cm.card .card-img,
.cm.card .card-img-bottom {
    border-bottom-right-radius: var(--cm-card-inner-border-radius);
    border-bottom-left-radius: var(--cm-card-inner-border-radius);
}

/* ===== CARD LAYOUTS ===== */

/* Card Group */
.cm.card-group {
    display: flex;
    flex-direction: column;
    gap: var(--cm-card-group-margin);
}

/* ===== CONTEXTUAL BACKGROUNDS ===== */

/* Card Contextual Backgrounds */
.cm.card.text-white .card-header,
.cm.card.text-white .card-footer {
    background-color: rgba(var(--cm-black-rgb), 0.1);
    border-color: rgba(var(--cm-black-rgb), 0.125);
}

.cm.card.bg-primary {
    --cm-card-bg: var(--cm-blue);
    --cm-card-color: var(--cm-white);
    --cm-card-border-color: var(--cm-blue);
