        margin: 0.25rem;
    }
}

/* Screen reader utilities */
.cm.card .visually-hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

/* Focus management for card groups */
.cm.card-group:focus-within .cm.card {
    position: relative;
    z-index: 1;
}

/* Enhanced focus styles for better accessibility */
.cm.card:focus-within {
    box-shadow: var(--cm-card-box-shadow), 0 0 0 2px var(--cm-primary);
    z-index: 2;
}

/* Ensure sufficient color contrast for all card variants */
@supports (color-contrast(white vs black)) {
    .cm.card {
        --cm-card-title-color: color-contrast(var(--cm-card-bg) vs var(--cm-black), var(--cm-white));
        --cm-card-color: color-contrast(var(--cm-card-bg) vs var(--cm-black), var(--cm-white));
    }
}

