/* =============================================================================
   SVG HERO BASE STYLES & ANIMATIONS (.cm.hero.svg-text)
   ============================================================================= */

/* Base SVG icon styles for heroes */
.cm.hero.svg-text .svg-float-container {
    display: block;
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
    background-color: var(--cm-white);

    /* Base animation - 0.5 second zoom in with very quick bounces from centre */
    opacity: 0;
    transform: scale(0);
    animation:
        bounce-in-fwd 0.5s 0.3s both,
        svgColorRipple 1.32s ease-out 1.0s;
    animation-fill-mode: forwards;
}

/* SVG bounce forward animation */
@keyframes bounce-in-fwd {
    0% {
        transform: scale(0);
        animation-timing-function: ease-in;
        opacity: 0;
    }

    38% {
        transform: scale(1);
        animation-timing-function: ease-out;
        opacity: 1;
    }

    55% {
        transform: scale(0.7);
        animation-timing-function: ease-in;
        opacity: 1;
    }

    72% {
        transform: scale(1);
        animation-timing-function: ease-out;
        opacity: 1;
    }

    81% {
        transform: scale(0.84);
        animation-timing-function: ease-in;
        opacity: 1;
    }

    89% {
        transform: scale(1);
        animation-timing-function: ease-out;
        opacity: 1;
    }

    95% {
        transform: scale(0.95);
        animation-timing-function: ease-in;
        opacity: 1;
    }

    100% {
        transform: scale(1);
        animation-timing-function: ease-out;
        opacity: 1;
    }
}

/* SVG color ripple animation - light blue flash for light mode icons */
@keyframes svgColorRipple {
    0% {
        background-color: rgb(255, 255, 255);
    }

    50% {
        background-color: rgb(208, 223, 232);
    }

    100% {
        background-color: rgb(255, 255, 255);
    }
}

/* SVG color ripple animation - light blue flash for dark mode icons */
@keyframes svgColorRippleDark {
    0% {
        background-color: rgb(10, 42, 61);
    }

    50% {
        background-color: rgb(208, 223, 232);
    }

    100% {
        background-color: rgb(10, 42, 61);
    }
}

