/* =============================================================================
   HERO ACCESSIBILITY ENHANCEMENTS
   ============================================================================= */

/* Note: Reduced motion handling for heroes is now in cm-theme.css
   This ensures that when themes are disabled, animations work normally,
   but when themes are enabled, reduced motion preferences are respected. */

/* High contrast mode adjustments */
@media (prefers-contrast: high) {
    .cm.hero.video::before {
        background: rgba(0, 0, 0, 0.5);
    }

    .cm.hero .text-white {
        text-shadow: 0 0 0 transparent, 0 0 5px rgba(0, 0, 0, 0.8);
    }

    /* SVG icons should be dark blue in high contrast mode */
    .cm.hero.svg-text .svg-float-container,
    .hero-container .svg-float-container {
        background-color: rgb(10, 42, 61);
    }
}

/* Dark mode specific adjustments when system/auto theme is set */
@media (prefers-color-scheme: dark) {

    [data-theme*="system"] .cm.hero.svg-text .svg-float-container,
    [data-theme*="auto"] .cm.hero.svg-text .svg-float-container,
    [data-theme*="system"] .hero-container .svg-float-container,
    [data-theme*="auto"] .hero-container .svg-float-container {
        background-color: rgb(10, 42, 61);
        animation:
            bounce-in-fwd 0.5s 0.3s both,
            svgColorRippleDark 1.32s ease-out 1.0s;
    }
}

/* Manual dark theme overrides */
[data-theme*="dark"] .cm.hero.svg-text .svg-float-container,
[data-theme*="dark"] .hero-container .svg-float-container {
    background-color: rgb(10, 42, 61);
    animation:
        bounce-in-fwd 0.5s 0.3s both,
        svgColorRippleDark 1.32s ease-out 1.0s;
}

