/* ===== /public/css/cm-layout.css ===== */
/* =====================================================
   CM DESIGN SYSTEM - LAYOUT & RESPONSIVE GRID
   ===================================================== */

/*
   Cardiff Met Layout System - Extended Bootstrap Grid
   
   This file contains the Cardiff Met responsive breakpoint system
   with custom xxxl breakpoint for ultra-wide displays.
   
   Breakpoints:
   - sm: 576px (540px container)
   - md: 768px (720px container) 
   - lg: 992px (960px container)
   - xl: 1200px (1140px container)
   - xxl: 1400px (1320px container)
   - xxxl: 1650px (1620px container) ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¯ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¿ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â½ Cardiff Met Extension
*/

/* ===== CARDIFF MET RESPONSIVE GRID SYSTEM ===== */

.row {
    --bs-gutter-x: calc(1 * var(--cm-gutter-x));
    --bs-gutter-y: calc(0 * var(--cm-gutter-y));
    display: flex;
    flex-wrap: wrap;
    margin-top: calc(-1 * var(--bs-gutter-y));
    margin-right: calc(-0.5 * var(--bs-gutter-x));
    margin-left: calc(-0.5 * var(--bs-gutter-x));
}

.container,
.container-fluid,
.container-xxxl,
.container-xxl,
.container-xl,
.container-lg,
.container-md,
.container-sm {
    --bs-gutter-x: var(--cm-gutter-x);
    --bs-gutter-y: var(--cm-gutter-y);
    width: 100%;
    padding-right: calc(var(--bs-gutter-x) * 0.5);
    padding-left: calc(var(--bs-gutter-x) * 0.5);
    margin-right: auto;
    margin-left: auto;
}

/* ===== RESPONSIVE BREAKPOINTS ===== */

@media (min-width: 576px) {

    .container-sm,
    .container {
        max-width: 540px;
    }
}

@media (min-width: 768px) {

    .container-md,
    .container-sm,
    .container {
        max-width: 720px;
    }
}

@media (min-width: 992px) {

    .container-lg,
    .container-md,
    .container-sm,
    .container {
        max-width: 960px;
    }
}

@media (min-width: 1200px) {

    .container-xl,
    .container-lg,
    .container-md,
    .container-sm,
    .container {
        max-width: 1140px;
    }
}

@media (min-width: 1400px) {

    .container-xxl,
    .container-xl,
    .container-lg,
    .container-md,
    .container-sm,
    .container {
        max-width: 1320px;
    }
}

@media (min-width: 1600px) {

    .container-xxxl,
    .container-xxl,
    .container-xl,
    .container-lg,
    .container-md,
    .container-sm,
    .container {
        max-width: 1580px;
    }
}

/* ===== CARDIFF MET UTILITY CLASSES ===== */

/* Ultra-wide responsive utilities for xxxl breakpoint */
@media (min-width: 1600px) {
    .d-xxxl-none {
        display: none !important;
    }

