/* =====================================================
   CM NAVCARDS OBJECT
   Navigation cards with image and text using Bootstrap 5
   ===================================================== */

/* ===============================================
   CM NAVCARDS SYSTEM
   =============================================== */

/* ===== BASE NAVCARD VARIABLES ===== */
.cm.navcards {
    /* Core Navcard Variables */
    --cm-navcards-gap: 1rem;
    --cm-navcards-border-radius: var(--cm-border-radius, 0.375rem);
    --cm-navcards-transition: all 0.2s ease-in-out;
    --cm-navcards-hover-opacity: var(--cm-opacity-hover-dark);
    --cm-navcards-shadow-hover: 0 8px 24px rgba(0, 0, 0, 0.15);

    /* Image styling */
    --cm-navcards-img-height: auto;
    --cm-navcards-img-bg: var(--cm-black);
    --cm-navcards-img-padding: 0;

    /* Title styling */
    --cm-navcards-title-size: 1.25rem;
    --cm-navcards-title-weight: 500;
    --cm-navcards-title-padding: 0.75rem;
    --cm-navcards-title-color: var(--cm-white);
    --cm-navcards-title-bg: var(--cm-dark-blue);

    /* Card styling */
    --cm-navcards-card-bg: var(--cm-white);
    --cm-navcards-card-border: none;
    --cm-navcards-card-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

/* ===== BASE NAVCARD CONTAINER ===== */
.cm.navcards {
    display: block;
    margin: 0;
    padding: 0;
}

/* ===== NAVCARD ROW ===== */
.cm.navcards .row {
    margin-right: calc(var(--cm-navcards-gap) * -0.5);
    margin-left: calc(var(--cm-navcards-gap) * -0.5);
}

.cm.navcards .row>[class*="col"] {
    padding-right: calc(var(--cm-navcards-gap) * 0.5);
    padding-left: calc(var(--cm-navcards-gap) * 0.5);
    margin-bottom: var(--cm-navcards-gap);
}

/* ===== NAVCARD LINK WRAPPER ===== */
.cm.navcards a {
    text-decoration: none;
    border-bottom: none;
    display: block;
    height: 100%;
    color: inherit;
    transition: var(--cm-navcards-transition);
}

.cm.navcards a:hover,
.cm.navcards a:focus {
    opacity: var(--cm-navcards-hover-opacity);
    border-bottom: none;
}

.cm.navcards a:focus {
    outline: 2px solid var(--cm-primary, var(--cm-dark-blue));
    outline-offset: 2px;
    border-radius: var(--cm-navcards-border-radius);
}

/* ===== NAVCARD IMAGE ===== */
.cm.navcards img {
    border-bottom: none;
}

/* ===== NAVCARD CARD COMPONENT ===== */
.cm.navcards .card {
    height: 100%;
    border: var(--cm-navcards-card-border);
    border-radius: var(--cm-navcards-border-radius);
    box-shadow: var(--cm-navcards-card-shadow);
    background-color: var(--cm-navcards-card-bg);
    overflow: hidden;
    transition: var(--cm-navcards-transition);
}

.cm.navcards a:hover .card,
.cm.navcards a:focus .card {
    box-shadow: var(--cm-navcards-shadow-hover);
}

/* ===== NAVCARD IMAGE ===== */
.cm.navcards .card-img-top {
    width: 100%;
    height: var(--cm-navcards-img-height);
    display: block;
    vertical-align: baseline;
    background-color: var(--cm-navcards-img-bg);
    padding: var(--cm-navcards-img-padding);
    border-radius: 0;
    border-top-left-radius: var(--cm-navcards-border-radius);
    border-top-right-radius: var(--cm-navcards-border-radius);
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
}

/* ===== NAVCARD BODY ===== */
.cm.navcards .card-body {
    padding: 0;
    background-color: var(--cm-navcards-title-bg);
    color: var(--cm-navcards-title-color);
}

/* ===== NAVCARD TITLE ===== */
.cm.navcards .card-title {
    font-size: var(--cm-navcards-title-size);
    font-weight: var(--cm-navcards-title-weight);
    line-height: 1.2;
    margin: 0;
    padding: var(--cm-navcards-title-padding);
    text-align: center;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

