/* ===== RESPONSIVE BEHAVIOR ===== */

/* X-Small devices (portrait phones, less than 576px) */
@media (max-width: 575.98px) {
    .cm.navcards {
        --cm-navcards-title-size: 1.125rem;
    }

    .cm.navcards .row {
        margin: 0 -0.5rem;
    }

    .cm.navcards .card-title {
        padding: 0.5rem 0.75rem;
        white-space: normal;
        word-wrap: break-word;
    }
}

/* Small devices (landscape phones, 576px to 768px) */
@media (min-width: 576px) and (max-width: 767.98px) {
    .cm.navcards {
        --cm-navcards-title-size: 1.125rem;
    }

    .cm.navcards .card-title {
        padding: 0.625rem 0.75rem;
    }
}

/* Medium devices (tablets, 768px to 992px) */
@media (min-width: 768px) and (max-width: 991.98px) {
    .cm.navcards {
        --cm-navcards-title-size: 1rem;
    }

    .cm.navcards .card-title {
        font-size: calc(0.9 * var(--cm-navcards-title-size));
        padding: 0.5rem;
    }
}

/* Large devices (desktops, 992px to 1200px) */
@media (min-width: 992px) and (max-width: 1199.98px) {
    .cm.navcards {
        --cm-navcards-title-size: 1.125rem;
    }

    .cm.navcards .card-title {
        font-size: calc(0.95 * var(--cm-navcards-title-size));
    }
}

/* ===== ACCESSIBILITY ENHANCEMENTS ===== */

/* Respect reduced motion preference */
@media (prefers-reduced-motion: reduce) {

    .cm.navcards a,
    .cm.navcards .card {
        transition: none;
    }

    .cm.navcards a:hover,
    .cm.navcards a:focus {
        transform: none;
    }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
    .cm.navcards .card {
        border: 2px solid var(--cm-navcards-title-bg);
    }

    .cm.navcards a:focus {
        outline-width: 3px;
    }
}

/* Forced colors mode (Windows High Contrast) */
@media (forced-colors: active) {
    .cm.navcards .card {
        border: 2px solid CanvasText;
        background-color: Canvas;
    }

    .cm.navcards .card-body {
        background-color: ButtonFace;
        color: ButtonText;
    }

    .cm.navcards a:focus {
        outline: 2px solid Highlight;
    }
}

/* Touch target sizing for mobile */
@media (max-width: 767px) {
    .cm.navcards a {
        min-height: 44px;
    }

    .cm.navcards .card {
        min-height: 150px;
    }
}

/* ===== UTILITY MODIFIERS ===== */

/* Compact variant */
.cm.navcards.compact {
    --cm-navcards-title-size: 1rem;
    --cm-navcards-title-padding: 0.5rem;
}

.cm.navcards.compact .card-img-top {
    height: 80px;
