/* cm btn overrides and updates  =================  */

.cm.btn.light-blue:hover,
.cm.btn.light-blue:focus {
    background-color: var(--cm-white) !important;
    color: var(--cm-dark-blue) !important;
    border: 1px solid var(--cm-dark-blue) !important;
}

