}

:root {
    --cm-callout-font-size: var(--cm-font-size-fluid);
}

/* cm jst widget and callout
   ================= */

/* JST Yellow Accent */
:root {
    --cm-callout-jst: rgb(251, 221, 111);
}

/* Containers */
.cm.jst-widget-container,
.cm.jst-callout-container {
    display: flex;
    align-items: center;
    min-height: 200px;
    height: 100%;
}

/* Callout */
.cm.callout.jst {
    --cm-callout-border-left-color: var(--cm-callout-jst);
    --cm-callout-bg: color-mix(in srgb, var(--cm-callout-jst) 5%, var(--cm-white) 95%);
    height: 100%;
    display: flex;
    align-items: center;
    margin: 0;
    padding: 1rem;
}

/* Widget */
.cm.jst-widget {
    background-color: var(--cm-callout-jst);
    padding: 2rem;
    border-radius: var(--cm-border-radius);
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.cm.jst-widget #scfsearchform {
    width: 100%;
    gap: 2rem !important;
}

.cm.jst-widget #scfsearchparam {
    flex: 1;
    width: 100% !important;
    border-radius: var(--cm-border-radius) !important;
}

.cm.jst-widget #scfsearch {
    display: flex;
    align-items: center;
    justify-content: center;
}

.jst-title {
    color: var(--cm-dark-blue);
    margin-bottom: 1.8rem;
}




/*** CM Learning Resources Index â€” Styles ========= */

/* --- Resource list --- */
.cm-resource-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.cm-resource-item {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    padding: 0.75rem 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.cm-resource-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.cm-resource-item:first-child {
    padding-top: 0;
}

/* --- Resource icon --- */
.cm-resource-icon {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.375rem;
    background-color: #f0f0f0;
    color: #555;
}

.cm-resource-icon .material-symbols-outlined {
    font-size: 1.125rem;
}

/* --- Resource content --- */
.cm-resource-content {
    flex: 1;
    min-width: 0;
}

.cm-resource-title {
    font-weight: 600;
    font-size: 0.95rem;
    line-height: 1.4;
    margin-bottom: 0.125rem;
}

.cm-resource-title a {
    text-decoration: none;
}

.cm-resource-title a:hover {
    text-decoration: none;
}

.cm-resource-desc {
    font-size: 0.85rem;
    color: #555;
    line-height: 1.5;
    margin-bottom: 0.25rem;
}

.cm-resource-source {
    font-size: 0.8rem;
    color: #777;
    line-height: 1.4;
}


.cm-resource-source a {
    color: #777;
    text-decoration: none;
}

.cm-resource-source a:hover {
    text-decoration: none;
}

.cm.accordion .accordion-body .cm-resource-content a {
    color: inherit;
    text-decoration: none;
    text-underline-offset: initial;
}

.cm-accordion-topic .accordion-button .cm-topic-icon {
    font-size: inherit;
    margin-right: 1rem;
}

/* Topic accordion icons */
.cm-accordion-topic .accordion-button .cm-topic-icon {
    color: var(--cm-dark-blue);
}

.cm-accordion-topic .accordion-button:hover .cm-topic-icon,
.cm-accordion-topic .accordion-button:focus .cm-topic-icon,
.cm-accordion-topic .accordion-button:active .cm-topic-icon {
    color: var(--cm-white);
}

.cm-accordion-topic .accordion-button:not(.collapsed) .cm-topic-icon {
    color: var(--cm-white);
}


/* --- Icon key --- */
.cm-resource-key {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-evenly;
    gap: 0.5rem 1.5rem;
    padding: 0.75rem 1rem;
    background-color: #f8f9fa;
    border-radius: 0.375rem;
    font-size: 0.85rem;
}

.cm-icon-key-item {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    color: #555;
}

.cm-icon-key-item .material-symbols-outlined {
    font-size: 1.125rem;
}

/* --- Empty / loading / error states --- */
.cm-empty-msg {
    font-size: 0.85rem;
    color: #999;
    font-style: italic;
    padding: 0.5rem 0;
}

.cm-error {
    text-align: center;
    padding: 2rem;
    color: #c00;
}